/**
 * @file src/lib/moveBlockedByExhaustionRule.ts
 * Dernier Recours et moves similaires : inutilisables tant qu'un autre move équipé a des PP.
 */

import type { MoveData } from '../types/combat.ts';

export interface MoveExhaustionCreature {
    currentMoves?: string[];
    movePp?: Record<string, { current: number; max?: number }>;
    isEnemy?: boolean;
}

function otherEquippedMoveHasPp(creature: MoveExhaustionCreature, moveName: string): boolean {
    const moves = creature.currentMoves;
    if (!moves || moves.length === 0) return false;

    for (const name of moves) {
        if (name === moveName) continue;
        const info = creature.movePp?.[name];
        // Conservateur : pas d'entrée movePp = considéré comme ayant des PP.
        if (!creature.movePp || !info || info.current > 0) return true;
    }
    return false;
}

/** Renvoie true si le move exige que tous les autres moves soient à 0 PP. */
export function moveBlockedByExhaustionRule(
    creature: MoveExhaustionCreature,
    moveName: string,
    moveDef: MoveData | Record<string, unknown> | null | undefined,
): boolean {
    if (!moveDef || !moveDef.requiresAllOtherMovesExhausted) return false;
    if (creature.isEnemy) return false;
    return otherEquippedMoveHasPp(creature, moveName);
}
