/** Élu team-wide multiplier when any ally carries the talent. */
export const ELU_TALENT_BOOST = 1.30;

/** Scale a fractional talent ratio (e.g. 0.25 capture bonus, 0.10 muraille). */
export function scaleTalentRatio(base: number, eluFactor: number): number {
    if (!Number.isFinite(base) || base <= 0) return base;
    if (!Number.isFinite(eluFactor) || eluFactor <= 1) return base;
    return base * eluFactor;
}

/** Scale a flat integer talent bonus (e.g. +6 ult charge from Épineux). */
export function scaleTalentFlat(base: number, eluFactor: number): number {
    if (!Number.isFinite(base) || base <= 0) return base;
    if (!Number.isFinite(eluFactor) || eluFactor <= 1) return base;
    return Math.floor(base * eluFactor);
}

/** Scale a multiplier above ×1 (e.g. Antivax ×2 → ×2.3 with Élu). */
export function scaleTalentMultiplierAboveOne(mult: number, eluFactor: number): number {
    if (!Number.isFinite(mult) || mult <= 1) return mult;
    if (!Number.isFinite(eluFactor) || eluFactor <= 1) return mult;
    return 1 + (mult - 1) * eluFactor;
}

/**
 * Robustesse ally PP-save: 25% per carrier with diminishing returns.
 * With Élu: per-stack rate becomes 25% × 1.30.
 */
export function computeRobustesseAllySaveChance(robustesseCount: number, eluActive: boolean): number {
    if (!Number.isFinite(robustesseCount) || robustesseCount <= 0) return 0;
    const perStackSave = eluActive ? 0.25 * ELU_TALENT_BOOST : 0.25;
    return 1 - Math.pow(1 - perStackSave, robustesseCount);
}

/** Phoenix proc chance capped at 100%. */
export function computePhoenixProcChance(eluFactor: number): number {
    const base = 0.25;
    if (!Number.isFinite(eluFactor) || eluFactor <= 1) return base;
    return Math.min(1, base * eluFactor);
}
