/**
 * Combat helpers for Technicien, Cran, and Force Brute passive talents.
 */

import {
    STATUS_EFFECTS,
    TECHNICIAN_POWER_THRESHOLD,
    TECHNICIAN_DAMAGE_BONUS,
    FORCE_BRUTE_DAMAGE_BONUS,
    CRAN_DEBUFF_FALLBACK_ATK_BONUS,
} from '../../constants/balance/talentsAndCombat.ts';
import { moveDefHasSecondaryEffects, moveHasSecondaryEffects } from './moveSecondaryEffects.ts';
import type { ICreature } from '../types/creature.ts';

type TalentBearer = Pick<ICreature, 'passiveTalent'> | { passiveTalent?: string | null };

export const DEBUFF_STATUSES = new Set<string>([
    STATUS_EFFECTS.PARALYZED,
    STATUS_EFFECTS.FROZEN,
    STATUS_EFFECTS.BURNED,
    STATUS_EFFECTS.POISONED,
    STATUS_EFFECTS.STUNNED,
    STATUS_EFFECTS.SLEEP,
    STATUS_EFFECTS.CONFUSED,
    STATUS_EFFECTS.SCARED,
    STATUS_EFFECTS.MIRED,
]);

/** Invert a status malus multiplier around 1.0 (e.g. 0.60 → 1.40). */
export function cranInvertMalusMultiplier(malusMult: number): number {
    return 2 - malusMult;
}

export function isDebuffStatus(type: string | null | undefined): boolean {
    return !!type && DEBUFF_STATUSES.has(type);
}

export function applyOffensivePassiveDamageTalents(
    attacker: TalentBearer,
    damage: number,
    opts: {
        movePower: number;
        moveName?: string;
        moveDef?: Record<string, unknown> | null;
        eluFactor?: number;
    },
): number {
    if (damage <= 0 || !attacker?.passiveTalent) return damage;
    const elu = opts.eluFactor ?? 1;
    let d = damage;

    if (attacker.passiveTalent === 'technicien' && opts.movePower <= TECHNICIAN_POWER_THRESHOLD) {
        d = Math.floor(d * (1 + TECHNICIAN_DAMAGE_BONUS * elu));
    }

    if (attacker.passiveTalent === 'force_brute') {
        const hasSecondary = opts.moveName
            ? moveHasSecondaryEffects(opts.moveName)
            : moveDefHasSecondaryEffects(opts.moveDef);
        if (hasSecondary) {
            d = Math.floor(d * (1 + FORCE_BRUTE_DAMAGE_BONUS * elu));
        }
    }

    return Math.max(1, d);
}

export function shouldSkipForceBruteSecondary(
    attacker: TalentBearer | null | undefined,
    moveName: string | undefined,
    moveDef?: Record<string, unknown> | null,
): boolean {
    if (!attacker || attacker.passiveTalent !== 'force_brute') return false;
    if (moveName) return moveHasSecondaryEffects(moveName);
    return moveDefHasSecondaryEffects(moveDef);
}

export function cranAttackStatusMultiplier(
    statusType: string,
    hasCran: boolean,
): number | null {
    if (!hasCran || !isDebuffStatus(statusType)) return null;
    if (statusType === STATUS_EFFECTS.SCARED) return cranInvertMalusMultiplier(0.60);
    return null;
}

export function cranSpeedStatusMultiplier(
    statusType: string,
    hasCran: boolean,
): number | null {
    if (!hasCran || !isDebuffStatus(statusType)) return null;
    if (statusType === STATUS_EFFECTS.PARALYZED) return cranInvertMalusMultiplier(0.75);
    if (statusType === STATUS_EFFECTS.MIRED) return cranInvertMalusMultiplier(0.60);
    return null;
}

export function cranFallbackAttackBonus(hasCran: boolean, statusType: string, eluFactor: number): number {
    if (!hasCran || !isDebuffStatus(statusType)) return 0;
    if (statusType === STATUS_EFFECTS.SCARED) return 0;
    return CRAN_DEBUFF_FALLBACK_ATK_BONUS * eluFactor;
}
