/**
 * @file src/lib/zRingCombat.ts
 * Combat hooks for active Z-Crystal effects.
 */

import { STATUS_EFFECTS } from '../../constants/balance/talentsAndCombat.ts';
import {
    Z_RING_DARKINIUM_ULT_DRAIN_FRAC,
    Z_RING_ELECTRIUM_FIRST_ATK_DMG_FRAC,
    Z_RING_FIRIUM_BURN_TICK_FRAC,
    Z_RING_FIRIUM_ENEMY_DAMAGE_FRAC,
    Z_RING_GRASSIUM_HEAL_FRAC,
    Z_RING_GROUNDIUM_FIRST_HIT_REDUCTION_FRAC,
    Z_RING_NORMALIUM_SPEED_FRAC,
    Z_RING_WATERIUM_SWITCH_HEAL_FRAC,
} from '../../constants/balance/zRing.ts';
import type { CreatureData, ICreature } from '../types/creature.js';
import type { GameRuntime } from '../types/game.js';
import {
    getActiveZCrystalId,
    getZEffectMultiplier,
    isZRingEffectsActive,
    isZRingWildCaptureCombat,
} from './zRingLogic.ts';
import { isTrainerBattle } from './combatHpRatio.ts';

function isUltimateReady(creature: CreatureData | null | undefined): boolean {
    if (!creature?.ultimateAbility) return true;
    if (creature.ultimateActive) return true;
    const needed = creature.ultimateAbility.chargeNeeded ?? 100;
    return (Number(creature.ultimateCharge) || 0) >= needed;
}

export function applyZRingWateriumSwitchHeal(
    game: GameRuntime,
    incoming: CreatureData,
): void {
    if (!isZRingEffectsActive(game)) return;
    if (getActiveZCrystalId(game) !== 'waterium') return;
    const mult = getZEffectMultiplier(game);
    const frac = Z_RING_WATERIUM_SWITCH_HEAL_FRAC * mult;
    const maxHp = Number(incoming.maxHp) || game.getPlayerMaxHp?.() || 1;
    const heal = Math.max(1, Math.floor(maxHp * frac));
    if (isTrainerBattle(game)) {
        incoming.currentHp = Math.min(maxHp, (Number(incoming.currentHp) || 0) + heal);
    } else {
        const cap = game.getPlayerMaxHp?.() ?? maxHp;
        incoming.mainAccountCurrentHp = Math.min(
            cap,
            (Number(incoming.mainAccountCurrentHp) || 0) + heal,
        );
    }
}

/** Normalium — +Speed while ultimate is not ready. */
export function getZRingNormaliumSpeedMult(game: GameRuntime): number {
    if (!isZRingEffectsActive(game)) return 1;
    if (getActiveZCrystalId(game) !== 'normalium') return 1;
    const c = game.currentPlayerCreature;
    if (!c || isUltimateReady(c)) return 1;
    const mult = getZEffectMultiplier(game);
    return 1 + Z_RING_NORMALIUM_SPEED_FRAC * mult;
}

/** Electrium E3 — once per combat: first player attack +25% damage. */
export function applyZRingElectriumOffensiveDamageMod(
    game: GameRuntime,
    attacker: ICreature | CreatureData | null | undefined,
    damage: number,
): number {
    if (damage <= 0) return damage;
    if (!isZRingEffectsActive(game)) return damage;
    if (getActiveZCrystalId(game) !== 'electrium') return damage;
    if (!attacker || attacker.isEnemy) return damage;
    if (!game.zRingCombat || game.zRingCombat.electriumFirstAtkUsed) return damage;
    game.zRingCombat.electriumFirstAtkUsed = true;
    const mult = getZEffectMultiplier(game);
    return Math.max(1, Math.floor(damage * (1 + Z_RING_ELECTRIUM_FIRST_ATK_DMG_FRAC * mult)));
}

/** Groundium G4 — once per combat: first hit taken −50% damage. */
export function applyZRingGroundiumIncomingDamageMod(
    game: GameRuntime,
    target: ICreature | CreatureData | null | undefined,
    damage: number,
): number {
    if (damage <= 0) return damage;
    if (!isZRingEffectsActive(game)) return damage;
    if (getActiveZCrystalId(game) !== 'groundium') return damage;
    if (!target || target.isEnemy) return damage;
    if (!game.zRingCombat || game.zRingCombat.groundiumGuardUsed) return damage;
    game.zRingCombat.groundiumGuardUsed = true;
    const mult = getZEffectMultiplier(game);
    const reduction = Math.min(0.9, Z_RING_GROUNDIUM_FIRST_HIT_REDUCTION_FRAC * mult);
    return Math.max(1, Math.floor(damage * (1 - reduction)));
}

/** Darkinium — drain enemy ultimate charge on each player attack. */
export function applyZRingDarkiniumUltDrain(
    game: GameRuntime,
    enemy: CreatureData | null | undefined,
): void {
    if (!isZRingEffectsActive(game)) return;
    if (getActiveZCrystalId(game) !== 'darkinium') return;
    if (!enemy?.ultimateAbility) return;
    const mult = getZEffectMultiplier(game);
    const needed = enemy.ultimateAbility.chargeNeeded ?? 100;
    const drain = Math.max(1, Math.floor(needed * Z_RING_DARKINIUM_ULT_DRAIN_FRAC * mult));
    enemy.ultimateCharge = Math.max(0, (Number(enemy.ultimateCharge) || 0) - drain);
}

export function applyZRingSpookiumOnAllyFaint(game: GameRuntime): void {
    if (!isZRingEffectsActive(game)) return;
    if (getActiveZCrystalId(game) !== 'spookium') return;
    if (!game.zRingCombat) return;
    const mult = getZEffectMultiplier(game);
    game.zRingCombat.enemyAtbSkips = Math.max(
        game.zRingCombat.enemyAtbSkips,
        Math.floor(1 * mult),
    );
}

export function consumeZRingEnemyAtbSkip(game: GameRuntime): boolean {
    const skips = game.zRingCombat?.enemyAtbSkips ?? 0;
    if (skips <= 0) return false;
    game.zRingCombat!.enemyAtbSkips = skips - 1;
    return true;
}

function enemyHasFiriumStatus(enemy: CreatureData): boolean {
    if (!enemy.hasStatusEffect?.()) return false;
    const type = enemy.statusEffect?.type;
    return type === STATUS_EFFECTS.BURNED || type === STATUS_EFFECTS.POISONED;
}

export function applyZRingFiriumBurnTick(game: GameRuntime, enemy: CreatureData | null | undefined): void {
    if (!isZRingEffectsActive(game)) return;
    if (getActiveZCrystalId(game) !== 'firium') return;
    if (!enemy || !enemyHasFiriumStatus(enemy)) return;
    const mult = getZEffectMultiplier(game);
    const maxHp = Number(enemy.maxHp) || 1;
    const tick = Math.max(1, Math.floor(maxHp * Z_RING_FIRIUM_BURN_TICK_FRAC * mult));
    if (typeof enemy.takeDamage === 'function') {
        enemy.takeDamage(tick, game.playerMainStats, false, '', 0, game);
    } else if (Number.isFinite(enemy.currentHp)) {
        enemy.currentHp = Math.max(0, (Number(enemy.currentHp) || 0) - tick);
    }
}

/** Firium — burned/poisoned enemies deal half damage. */
export function applyZRingFiriumEnemyDamageMod(
    game: GameRuntime,
    attacker: ICreature | CreatureData | null | undefined,
    damage: number,
): number {
    if (damage <= 0) return damage;
    if (!isZRingEffectsActive(game)) return damage;
    if (getActiveZCrystalId(game) !== 'firium') return damage;
    if (!attacker?.isEnemy || !enemyHasFiriumStatus(attacker)) return damage;
    const mult = getZEffectMultiplier(game);
    const keepFrac = Math.max(0.1, 1 - Z_RING_FIRIUM_ENEMY_DAMAGE_FRAC * mult);
    return Math.max(1, Math.floor(damage * keepFrac));
}

/** Grassium R3 combat heal — 2% max HP on each player attack. */
export function applyZRingGrassiumOnPlayerAttack(game: GameRuntime): void {
    if (!isZRingEffectsActive(game)) return;
    if (getActiveZCrystalId(game) !== 'grassium') return;
    const c = game.currentPlayerCreature;
    if (!c) return;
    const mult = getZEffectMultiplier(game);
    const maxHp = isTrainerBattle(game)
        ? (Number(c.maxHp) || 1)
        : (game.getPlayerMaxHp?.() ?? (Number(c.maxHp) || 1));
    const heal = Math.max(1, Math.floor(maxHp * Z_RING_GRASSIUM_HEAL_FRAC * mult));
    if (isTrainerBattle(game)) {
        c.currentHp = Math.min(maxHp, (Number(c.currentHp) || 0) + heal);
    } else {
        c.mainAccountCurrentHp = Math.min(
            maxHp,
            (Number(c.mainAccountCurrentHp) || 0) + heal,
        );
    }
}

export function canZRingGrassiumRetry(game: GameRuntime): boolean {
    if (!isZRingWildCaptureCombat(game)) return false;
    if (game.captureMode !== 2) return false;
    if (getActiveZCrystalId(game) !== 'grassium') return false;
    if (game.zRingCombat?.grassiumRetryUsed) return false;
    return true;
}

export function markZRingGrassiumRetryUsed(game: GameRuntime): void {
    if (!game.zRingCombat) return;
    game.zRingCombat.grassiumRetryUsed = true;
    game.zRingCombat.grassiumFreeThrowPending = true;
}

export function consumeZRingGrassiumFreeThrow(game: GameRuntime): boolean {
    if (!game.zRingCombat?.grassiumFreeThrowPending) return false;
    game.zRingCombat.grassiumFreeThrowPending = false;
    return true;
}
