/**
 * Opponent roster resolution for trainer-mode team talents (Piègeur, Médiateur, Sentinelle).
 */

import type { GameRuntime } from '../types/game.ts';
import type { CreatureData, ICreature } from '../types/creature.ts';

export type TrainerTeamMember = CreatureData | ICreature | null | undefined;

/** Subway, arena, gym, or tower — modes with a multi-Pokémon opponent roster. */
export function isTrainerCombatMode(game: GameRuntime): boolean {
    return !!(game.subwayState?.isActive)
        || !!(game.arenaState?.active)
        || !!(game.gymTrainerState?.active)
        || !!(game.towerState?.isActive);
}

/** Opponent roster (bench carriers included). */
export function resolveOpponentTeamForTrainerCombat(game: GameRuntime): TrainerTeamMember[] | null {
    if (game.subwayState?.isActive && Array.isArray(game.subwayState.enemyTeam)) {
        return game.subwayState.enemyTeam;
    }
    if (game.arenaState?.active && Array.isArray(game.arenaState.championTeam)) {
        return game.arenaState.championTeam;
    }
    if (game.towerState?.isActive && Array.isArray(game.towerState.enemyTeam)) {
        return game.towerState.enemyTeam;
    }
    if (game.gymTrainerState?.active) {
        const gymTeam = (game.gymTrainerState as { team?: TrainerTeamMember[] }).team;
        if (Array.isArray(gymTeam) && gymTeam.length > 0) return gymTeam;
        if (game.currentEnemy) return [game.currentEnemy];
    }
    return null;
}

export function countPassiveTalentOnTeam(
    team: TrainerTeamMember[] | null | undefined,
    talent: string,
): number {
    if (!Array.isArray(team)) return 0;
    return team.filter((member) => member && member.passiveTalent === talent).length;
}

/** Index of a fainted opponent in the trainer roster (-1 if unknown). */
export function resolveOpponentFaintedIndex(
    game: GameRuntime,
    fainted: TrainerTeamMember,
): number {
    const team = resolveOpponentTeamForTrainerCombat(game);
    if (!team || !fainted) return -1;
    const direct = team.indexOf(fainted);
    if (direct >= 0) return direct;

    if (game.subwayState?.isActive) {
        return Math.max(0, (game.subwayState.currentEnemyIndex ?? 0));
    }
    if (game.arenaState?.active) {
        return Math.max(0, (game.arenaState.currentChampionIndex ?? 0));
    }
    if (game.towerState?.isActive) {
        return Math.max(0, (game.towerState.currentEnemyIndex ?? 0));
    }
    if (game.gymTrainerState?.active) {
        const gts = game.gymTrainerState as { currentIndex?: number };
        return Math.max(0, (gts.currentIndex ?? 0));
    }
    return -1;
}

/** Médiateur stack count (whole team, including benched). */
export function resolveMediateurStackCount(
    game: GameRuntime,
    bearer: { isEnemy?: boolean; passiveTalent?: string | null },
): number {
    if (bearer.passiveTalent !== 'mediateur') return 0;
    if (bearer.isEnemy) {
        const opp = resolveOpponentTeamForTrainerCombat(game);
        return Math.max(1, countPassiveTalentOnTeam(opp, 'mediateur'));
    }
    if (Array.isArray(game.playerTeam)) {
        return Math.max(1, countPassiveTalentOnTeam(game.playerTeam, 'mediateur'));
    }
    return 1;
}
