/**
 * Battle Subway exclusive held item combat helpers.
 */

import type { GameRuntime } from '../types/game.js';
import type { ICreature } from '../types/creature.js';

const TERRAIN_EXTENDER_REMOVAL_DIVISOR = 1.5;
const PUNCHING_GLOVE_DAMAGE_MULT = 0.10;
const METRONOME_BAND_STEP = 0.05;
const METRONOME_BAND_MAX_STACKS = 5;

type HeldCreature = ICreature & {
    name?: string;
    heldItem?: string | null;
    _blunderPolicyUsed?: boolean;
    _weaknessPolicyUsed?: boolean;
    _metronomeBandStacks?: number;
    adjustCombatStatStage?: (stat: string, delta: number) => number;
};

export function scaleRemovalChanceForTerrainExtender(
    removalChance: number,
    sourceAttacker: { heldItem?: string | null } | null | undefined,
): number {
    if (removalChance <= 0) return removalChance;
    if (sourceAttacker?.heldItem !== 'terrain_extender') return removalChance;
    return removalChance / TERRAIN_EXTENDER_REMOVAL_DIVISOR;
}

export function applyBlunderPolicyOnMiss(
    attacker: HeldCreature,
    game: GameRuntime | null | undefined,
    logFn?: (msg: string) => void,
): boolean {
    if (!attacker || attacker.heldItem !== 'blunder_policy') return false;
    if (attacker._blunderPolicyUsed) return false;
    attacker._blunderPolicyUsed = true;
    if (typeof attacker.adjustCombatStatStage === 'function') {
        attacker.adjustCombatStatStage('attack', 2);
        attacker.adjustCombatStatStage('speed', 2);
    }
    const lang = game?.normalizeLanguage?.(game.language) === 'en' ? 'en' : 'fr';
    const msg = lang === 'en'
        ? `${attacker.name ?? 'Holder'}'s Blunder Policy: +20% ATK, +20% SPE!`
        : `Assurance Échec de ${attacker.name ?? 'Porteur'} : +20% Att., +20% Vit. !`;
    if (logFn) logFn(msg);
    return true;
}

export function applyWeaknessPolicyOnSuperEffectiveHit(
    defender: HeldCreature,
    game: GameRuntime | null | undefined,
    logFn?: (msg: string) => void,
): boolean {
    if (!defender || defender.heldItem !== 'weakness_policy') return false;
    if (defender._weaknessPolicyUsed) return false;
    defender._weaknessPolicyUsed = true;
    if (typeof defender.adjustCombatStatStage === 'function') {
        defender.adjustCombatStatStage('attack', 2);
        defender.adjustCombatStatStage('spattack', 2);
    }
    const lang = game?.normalizeLanguage?.(game.language) === 'en' ? 'en' : 'fr';
    const msg = lang === 'en'
        ? `${defender.name ?? 'Holder'}'s Weakness Policy: +20% ATK, +20% Sp. Atk!`
        : `Politique de Faiblesse de ${defender.name ?? 'Porteur'} : +20% Att., +20% Att. Sp. !`;
    if (logFn) logFn(msg);
    return true;
}

export function shouldBlockNegativeStatStage(
    creature: { heldItem?: string | null } | null | undefined,
    delta: number,
): boolean {
    return delta < 0 && creature?.heldItem === 'clear_amulet';
}

export function isContactBlockedByPunchingGlove(
    attacker: { heldItem?: string | null } | null | undefined,
    damageCategory: string,
): boolean {
    return attacker?.heldItem === 'punching_glove' && damageCategory === 'physical';
}

export function getPunchingGloveDamageMult(
    attacker: { heldItem?: string | null } | null | undefined,
    attackCategory: string,
): number {
    if (attacker?.heldItem !== 'punching_glove' || attackCategory !== 'physical') return 1;
    return 1 + PUNCHING_GLOVE_DAMAGE_MULT;
}

export function getMetronomeBandDamageMult(
    attacker: { heldItem?: string | null; _metronomeBandStacks?: number } | null | undefined,
): number {
    if (attacker?.heldItem !== 'metronome_band') return 1;
    const stacks = Math.max(0, Math.min(METRONOME_BAND_MAX_STACKS, Math.floor(Number(attacker._metronomeBandStacks) || 0)));
    return 1 + stacks * METRONOME_BAND_STEP;
}

export function incrementMetronomeBandOnHit(
    attacker: { heldItem?: string | null; _metronomeBandStacks?: number } | null | undefined,
): void {
    if (!attacker || attacker.heldItem !== 'metronome_band') return;
    const prev = Math.max(0, Math.floor(Number(attacker._metronomeBandStacks) || 0));
    attacker._metronomeBandStacks = Math.min(METRONOME_BAND_MAX_STACKS, prev + 1);
}

export function resetMetronomeBand(
    creature: { _metronomeBandStacks?: number } | null | undefined,
): void {
    if (!creature) return;
    creature._metronomeBandStacks = 0;
}

export function resetSubwayHeldBattleFlags(
    creature: HeldCreature | null | undefined,
): void {
    if (!creature) return;
    creature._blunderPolicyUsed = false;
    creature._weaknessPolicyUsed = false;
}

export function resolveLoadedDiceHitFloor(minHits: number, maxHits: number): number {
    if (maxHits <= 1) return minHits;
    return Math.min(maxHits, Math.max(minHits, Math.min(4, maxHits)));
}
