/**
 * @file src/lib/moveSecondaryEffects.ts
 * Effets secondaires des moves (statuts + stages de stats) issus de PokeAPI.
 */

import { getMoveDefinition } from '../../constants/movesDb.ts';
import { STATUS_EFFECTS, MOVE_SECONDARY_EFFECT_CHANCE_MULT, ECRAN_POUDRE_SECONDARY_CHANCE_MULT } from '../../constants/balance/talentsAndCombat.ts';
import { scaleTalentRatio } from './eluTalentBoost.ts';
import type { CombatStatKey, MoveData, MoveSecondaryEffects, MoveStatChange } from '../types/combat.ts';
import type { GameRuntime } from '../types/game.js';
import type { ICreature } from '../types/creature.js';

const BUFF_STATUSES = new Set([
    STATUS_EFFECTS.REINFORCED,
    STATUS_EFFECTS.AGILE,
    STATUS_EFFECTS.THORNY,
    STATUS_EFFECTS.ENRAGED,
    STATUS_EFFECTS.PUNCHER,
]);

export interface MoveSecondaryProcEvent {
    kind: 'status' | 'stat';
    creature: ICreature;
    status?: string;
    statusLabel?: string;
    stat?: CombatStatKey;
    stages?: number;
    stageLabel?: string;
}

export function scaleSecondaryChance(
    chance: number,
    opts?: {
        attacker?: { passiveTalent?: string | null };
        game?: GameRuntime | null;
    },
): number {
    if (!Number.isFinite(chance) || chance <= 0) return 0;
    const mult = Number(MOVE_SECONDARY_EFFECT_CHANCE_MULT);
    let scaled = chance * (Number.isFinite(mult) && mult > 0 ? mult : 1);
    if (opts?.attacker?.passiveTalent === 'ecran_poudre') {
        let ecranMult = ECRAN_POUDRE_SECONDARY_CHANCE_MULT;
        if (opts.game && typeof opts.game.getEluFactorFor === 'function') {
            ecranMult = scaleTalentRatio(ecranMult, opts.game.getEluFactorFor(opts.attacker));
        }
        scaled *= ecranMult;
    }
    return Math.max(0, Math.min(1, scaled));
}

export function getMoveSecondaryEffects(moveName: string): MoveSecondaryEffects | null {
    const move = getMoveDefinition(moveName) as MoveData | null;
    if (!move) return null;
    const hasStatus = move.status && typeof move.statusChance === 'number' && move.statusChance > 0;
    const hasStats = Array.isArray(move.statChanges) && move.statChanges.length > 0;
    if (!hasStatus && !hasStats) return null;
    return {
        status: move.status,
        statusChance: move.statusChance,
        statusTarget: move.statusTarget,
        statChanges: move.statChanges,
    };
}

export function moveDefHasSecondaryEffects(move: MoveData | Record<string, unknown> | null | undefined): boolean {
    if (!move) return false;
    const hasStatus = move.status && typeof move.statusChance === 'number' && move.statusChance > 0;
    const hasStats = Array.isArray(move.statChanges) && move.statChanges.length > 0;
    return !!(hasStatus || hasStats);
}

export function moveHasSecondaryEffects(moveName: string): boolean {
    return moveDefHasSecondaryEffects(getMoveDefinition(moveName));
}

function combatLang(game: GameRuntime | null | undefined): 'fr' | 'en' {
    const lang = game?.language;
    return String(lang || 'fr').toLowerCase().startsWith('en') ? 'en' : 'fr';
}

export function formatStatLabel(game: GameRuntime | null | undefined, stat: CombatStatKey): string {
    const keyMap: Record<CombatStatKey, string> = {
        attack: 'modal.creature.atkShort',
        spattack: 'modal.creature.spAtkShort',
        defense: 'modal.creature.defShort',
        spdefense: 'modal.creature.spDefShort',
        speed: 'modal.creature.speedShort',
        accuracy: 'modal.creature.moveTooltip.accuracyShort',
        evasion: 'modal.creature.moveTooltip.evasionShort',
    };
    const key = keyMap[stat];
    if (game && typeof game.t === 'function') {
        const translated = game.t(key);
        if (translated && translated !== key) return translated;
    }
    const fr: Record<CombatStatKey, string> = {
        attack: 'Att',
        spattack: 'Atq.Sp',
        defense: 'Déf',
        spdefense: 'Déf.Sp',
        speed: 'Vit',
        accuracy: 'Préc',
        evasion: 'Esqu',
    };
    const en: Record<CombatStatKey, string> = {
        attack: 'Atk',
        spattack: 'Sp.Atk',
        defense: 'Def',
        spdefense: 'Sp.Def',
        speed: 'Spe',
        accuracy: 'Acc',
        evasion: 'Eva',
    };
    return combatLang(game) === 'en' ? en[stat] : fr[stat];
}

export function formatStatusLabel(game: GameRuntime | null | undefined, status: string): string {
    const key = `modal.creature.moveTooltip.status.${status}`;
    if (game && typeof game.t === 'function') {
        const translated = game.t(key);
        if (translated && translated !== key) return translated;
    }
    const fr: Record<string, string> = {
        burned: 'Brûlure',
        poisoned: 'Poison',
        paralyzed: 'Paralysie',
        frozen: 'Gel',
        confused: 'Confusion',
        stunned: 'Étourdissement',
        sleep: 'Sommeil',
        scared: 'Peur',
        reinforced: 'Renfort',
        agile: 'Agilité',
        thorny: 'Épines',
        enraged: 'Enragement',
        puncher: 'Puncheur',
        mired: 'Embourbement',
    };
    const en: Record<string, string> = {
        burned: 'Burn',
        poisoned: 'Poison',
        paralyzed: 'Paralysis',
        frozen: 'Freeze',
        confused: 'Confusion',
        stunned: 'Stun',
        sleep: 'Sleep',
        scared: 'Fear',
        reinforced: 'Reinforced',
        agile: 'Agile',
        thorny: 'Thorns',
        enraged: 'Enraged',
        puncher: 'Puncher',
        mired: 'Mired',
    };
    const map = combatLang(game) === 'en' ? en : fr;
    return map[status] || status;
}

export function formatStatusFloatingText(game: GameRuntime | null | undefined, status: string): string {
    const label = formatStatusLabel(game, status).toUpperCase();
    if (label.length <= 8) return label;
    return label.slice(0, 8);
}

export function formatStatStageFloatingText(
    game: GameRuntime | null | undefined,
    stat: CombatStatKey,
    stages: number,
): string {
    const statLabel = formatStatLabel(game, stat);
    const short = statLabel.length > 3 ? statLabel.slice(0, 3).toUpperCase() : statLabel.toUpperCase();
    const sign = stages > 0 ? '+' : '';
    return `${sign}${stages} ${short}`;
}

function resolveEffectCreature(
    attacker: ICreature,
    target: ICreature,
    effectTarget: 'self' | 'opponent',
): ICreature {
    return effectTarget === 'self' ? attacker : target;
}

function recordMoveStatStageMetrics(
    game: GameRuntime | null | undefined,
    attacker: ICreature,
    stat: CombatStatKey,
    stages: number,
): void {
    if (!attacker.isEnemy && game && typeof game.recordStatStageApplication === 'function') {
        game.recordStatStageApplication(attacker, stat, stages, 'move');
    }
}

function recordMoveStatusMetrics(
    game: GameRuntime | null | undefined,
    attacker: ICreature,
    status: string,
): void {
    if (!attacker.isEnemy && game) {
        if (!game.stats || typeof game.stats !== 'object') {
            game.stats = {} as NonNullable<GameRuntime['stats']>;
        }
        game.stats.statusInflicted = (game.stats.statusInflicted || 0) + 1;
        game.stats.moveStatusInflicted = (game.stats.moveStatusInflicted || 0) + 1;
        if (!game.stats.moveStatusInflictedByType || typeof game.stats.moveStatusInflictedByType !== 'object') {
            game.stats.moveStatusInflictedByType = {};
        }
        game.stats.moveStatusInflictedByType[status] = (game.stats.moveStatusInflictedByType[status] || 0) + 1;
        if (typeof game.checkAchievements === 'function') {
            game.checkAchievements('statusInflicted');
            game.checkAchievements('moveStatusInflicted');
            game.checkAchievements(`moveStatusInflicted_${status}`);
        }
        if (typeof game.checkSpecialQuests === 'function') game.checkSpecialQuests('statusInflicted');
        if (typeof game.recordStatusApplication === 'function') {
            game.recordStatusApplication(attacker, status, 'move');
        }
    }
}

function applyMoveStatusEffect(
    ctx: {
        game?: GameRuntime | null;
        attacker: ICreature;
        target: ICreature;
        move: MoveSecondaryEffects;
        sourceAttack: number;
        log?: (msg: string) => void;
        onProc?: (event: MoveSecondaryProcEvent) => void;
    },
): void {
    const { game, attacker, target, move, sourceAttack, log, onProc } = ctx;
    const status = move.status;
    const chance = scaleSecondaryChance(move.statusChance ?? 0, { attacker, game });
    if (!status || chance <= 0) return;
    if (Math.random() >= chance) return;

    let effectTarget: 'self' | 'opponent' = move.statusTarget || 'opponent';
    if (BUFF_STATUSES.has(status)) {
        effectTarget = 'self';
    }
    const creature = resolveEffectCreature(attacker, target, effectTarget);
    if (!creature.applyStatusEffect) return;
    if (creature.hasStatusEffect && creature.hasStatusEffect()) return;

    const applied = creature.applyStatusEffect(status, sourceAttack, attacker);
    if (!applied) return;

    const statusName = typeof creature.getStatusEffectName === 'function'
        ? creature.getStatusEffectName()
        : formatStatusLabel(game, status);

    if (log) {
        const fr = `${creature.name} est maintenant ${statusName} !`;
        const en = `${creature.name} is now ${statusName}!`;
        log(combatLang(game) === 'en' ? en : fr);
    }

    recordMoveStatusMetrics(game, attacker, status);

    if (onProc) {
        onProc({
            kind: 'status',
            creature,
            status,
            statusLabel: statusName,
        });
    }
}

function applyMoveStatChange(
    ctx: {
        game?: GameRuntime | null;
        attacker: ICreature;
        target: ICreature;
        change: MoveStatChange;
        log?: (msg: string) => void;
        onProc?: (event: MoveSecondaryProcEvent) => void;
    },
): void {
    const { game, attacker, target, change, log, onProc } = ctx;
    if (!change || !change.stat || !change.stages) return;
    const chance = scaleSecondaryChance(change.chance ?? 0, { attacker, game });
    if (chance <= 0) return;
    if (Math.random() >= chance) return;

    const creature = resolveEffectCreature(attacker, target, change.target);
    if (typeof creature.adjustCombatStatStage !== 'function') return;
    const applied = creature.adjustCombatStatStage(change.stat, change.stages);
    if (applied === 0) return;

    const statLabel = formatStatLabel(game, change.stat);
    const stageLabel = change.stages > 0 ? `+${change.stages}` : String(change.stages);

    if (log) {
        const targetLabel = change.target === 'self'
            ? (combatLang(game) === 'en' ? 'user' : 'lanceur')
            : (combatLang(game) === 'en' ? 'target' : 'cible');
        const fr = `${creature.name} : ${stageLabel} ${statLabel} (${targetLabel})`;
        const en = `${creature.name}: ${stageLabel} ${statLabel} (${targetLabel})`;
        log(combatLang(game) === 'en' ? en : fr);
    }

    recordMoveStatStageMetrics(game, attacker, change.stat, applied);

    if (onProc) {
        onProc({
            kind: 'stat',
            creature,
            stat: change.stat,
            stages: change.stages,
            stageLabel: `${stageLabel} ${statLabel}`,
        });
    }
}

export function applyMoveSecondaryEffects(ctx: {
    game?: GameRuntime | null;
    attacker: ICreature;
    target: ICreature;
    move: MoveData | MoveSecondaryEffects | Record<string, unknown>;
    appliedDamage: number;
    sourceAttack: number;
    log?: (msg: string) => void;
    onProc?: (event: MoveSecondaryProcEvent) => void;
}): void {
    const { move, appliedDamage } = ctx;
    if (!appliedDamage || appliedDamage <= 0) return;

    const effects: MoveSecondaryEffects = {
        status: typeof move.status === 'string' ? move.status : undefined,
        statusChance: typeof move.statusChance === 'number' ? move.statusChance : undefined,
        statusTarget: move.statusTarget === 'self' || move.statusTarget === 'opponent' ? move.statusTarget : undefined,
        statChanges: Array.isArray(move.statChanges) ? move.statChanges as MoveStatChange[] : undefined,
    };

    applyMoveStatusEffect({ ...ctx, move: effects });
    for (const change of effects.statChanges || []) {
        applyMoveStatChange({ ...ctx, change });
    }
}

export function formatMoveSecondaryTooltipParts(
    game: GameRuntime,
    move: MoveData | Record<string, unknown>,
): string[] {
    const parts: string[] = [];
    const status = typeof move.status === 'string' ? move.status : '';
    const statusChance = Number(move.statusChance);
    if (status && Number.isFinite(statusChance) && statusChance > 0) {
        const displayChance = Math.round(scaleSecondaryChance(statusChance) * 100);
        const key = 'modal.creature.moveTooltip.statusChance';
        const raw = typeof game.t === 'function'
            ? game.t(key, { percent: displayChance, status: formatStatusLabel(game, status) })
            : key;
        if (raw && raw !== key) parts.push(raw);
    }

    const statChanges = Array.isArray(move.statChanges) ? move.statChanges as MoveStatChange[] : [];
    for (const change of statChanges) {
        const chance = Number(change.chance);
        if (!Number.isFinite(chance) || chance <= 0) continue;
        const stageLabel = change.stages > 0 ? `+${change.stages}` : String(change.stages);
        const statLabel = formatStatLabel(game, change.stat);
        const targetKey = change.target === 'self'
            ? 'modal.creature.moveTooltip.statTargetSelf'
            : 'modal.creature.moveTooltip.statTargetOpponent';
        const targetLabel = typeof game.t === 'function' ? game.t(targetKey) : targetKey;
        const key = 'modal.creature.moveTooltip.statChange';
        const percent = Math.round(scaleSecondaryChance(chance) * 100);
        const raw = typeof game.t === 'function'
            ? game.t(key, { percent, stages: stageLabel, stat: statLabel, target: targetLabel })
            : key;
        if (raw && raw !== key) parts.push(raw);
    }

    return parts;
}
