/**
 * @file constants/pokerus.ts
 * Pokérus duration shared by Creature (infection) and zoneSystem (wild spawn).
 */

/** Default infection duration (ms) when not overridden by balance. */
export const POKERUS_DURATION_MS = 48 * 60 * 60 * 1000;

/** Per-roll spread chance (team: one roll per second per group member). */
export const POKERUS_TEAM_SPREAD_CHANCE = 1 / 32768;
/** Pension: one roll every 15 s per group member. */
export const POKERUS_PENSION_SPREAD_CHANCE = 1 / 65536;
/** Storage: one roll per hour per group member. */
export const POKERUS_STORAGE_SPREAD_CHANCE = 1 / 131072;

if (typeof globalThis !== 'undefined') {
    (globalThis as Record<string, unknown>).POKERUS_DURATION_MS = POKERUS_DURATION_MS;
}
if (typeof window !== 'undefined') {
    (window as unknown as Record<string, unknown>).POKERUS_DURATION_MS = POKERUS_DURATION_MS;
}
