/**
 * Pokémon personality natures — official 25 (+10% / -10% on combat stats).
 */

export type NatureStatKey = 'attack' | 'spattack' | 'defense' | 'spdefense' | 'speed';

export interface NatureDef {
    id: string;
    boostStat: NatureStatKey | null;
    reduceStat: NatureStatKey | null;
}

export const NATURE_BOOST_MULT = 1.10;
export const NATURE_REDUCE_MULT = 0.90;

export const DEFAULT_NATURE_ID = 'Hardi';

/** All 25 official natures (French ids — primary game locale). */
export const POKEMON_NATURES: readonly NatureDef[] = [
    { id: 'Hardi', boostStat: null, reduceStat: null },
    { id: 'Solo', boostStat: 'attack', reduceStat: 'defense' },
    { id: 'Brave', boostStat: 'attack', reduceStat: 'speed' },
    { id: 'Rigide', boostStat: 'attack', reduceStat: 'spattack' },
    { id: 'Mauvais', boostStat: 'attack', reduceStat: 'spdefense' },
    { id: 'Docile', boostStat: null, reduceStat: null },
    { id: 'Malin', boostStat: 'defense', reduceStat: 'attack' },
    { id: 'Assuré', boostStat: 'defense', reduceStat: 'speed' },
    { id: 'Malpoli', boostStat: 'defense', reduceStat: 'spattack' },
    { id: 'Lâche', boostStat: 'defense', reduceStat: 'spdefense' },
    { id: 'Timide', boostStat: 'speed', reduceStat: 'attack' },
    { id: 'Pressé', boostStat: 'speed', reduceStat: 'defense' },
    { id: 'Jovial', boostStat: 'speed', reduceStat: 'spattack' },
    { id: 'Naïf', boostStat: 'speed', reduceStat: 'spdefense' },
    { id: 'Modeste', boostStat: 'spattack', reduceStat: 'attack' },
    { id: 'Doux', boostStat: 'spattack', reduceStat: 'defense' },
    { id: 'Discret', boostStat: 'spattack', reduceStat: 'speed' },
    { id: 'Foufou', boostStat: 'spattack', reduceStat: 'spdefense' },
    { id: 'Calme', boostStat: 'spdefense', reduceStat: 'attack' },
    { id: 'Gentil', boostStat: 'spdefense', reduceStat: 'defense' },
    { id: 'Prudent', boostStat: 'spdefense', reduceStat: 'spattack' },
    { id: 'Malveillant', boostStat: 'spdefense', reduceStat: 'speed' },
    { id: 'Pudique', boostStat: null, reduceStat: null },
    { id: 'Bizarre', boostStat: null, reduceStat: null },
    { id: 'Sérieux', boostStat: null, reduceStat: null },
] as const;

const NATURE_BY_ID = new Map<string, NatureDef>(
    POKEMON_NATURES.map((n) => [n.id, n]),
);

export function isValidNatureId(id: string): boolean {
    return NATURE_BY_ID.has(id);
}

export function normalizeNatureId(raw: string | null | undefined): string {
    if (raw && isValidNatureId(raw)) return raw;
    return DEFAULT_NATURE_ID;
}

export function getNatureDef(natureId: string): NatureDef {
    return NATURE_BY_ID.get(natureId) ?? NATURE_BY_ID.get(DEFAULT_NATURE_ID)!;
}

export function getAllNatureIds(): string[] {
    return POKEMON_NATURES.map((n) => n.id);
}

export function pickRandomNature(): string {
    const idx = Math.floor(Math.random() * POKEMON_NATURES.length);
    return POKEMON_NATURES[idx]?.id ?? DEFAULT_NATURE_ID;
}

export type NatureStatMultipliers = Record<NatureStatKey, number>;

export function getNatureStatMultipliers(natureId: string): NatureStatMultipliers {
    const mults: NatureStatMultipliers = {
        attack: 1,
        spattack: 1,
        defense: 1,
        spdefense: 1,
        speed: 1,
    };
    const def = getNatureDef(natureId);
    if (def.boostStat) mults[def.boostStat] = NATURE_BOOST_MULT;
    if (def.reduceStat) mults[def.reduceStat] = NATURE_REDUCE_MULT;
    return mults;
}

export function applyNatureToStatValue(value: number, statKey: NatureStatKey, natureId: string): number {
    const mults = getNatureStatMultipliers(natureId);
    return Math.floor(value * mults[statKey]);
}
