/**
 * @file src/lib/rampageMove.ts
 * Famille furie (Colère / Outrage) : verrou 2–3 actions puis confusion.
 */

import { STATUS_EFFECTS } from '../../constants/balance/talentsAndCombat.ts';
import { formatStatusFloatingText, formatStatusLabel } from './moveSecondaryEffects.ts';
import type { GameRuntime } from '../types/game.js';
import type { CreatureData, ICreature } from '../types/creature.js';
import type { MoveRampage } from '../types/combat.ts';

const BLOCKING_RAMPAGE_CONFUSION = new Set([
    STATUS_EFFECTS.FROZEN,
    STATUS_EFFECTS.STUNNED,
    STATUS_EFFECTS.SLEEP,
]);

export type RampageState = { moveName: string; remaining: number };

function combatLang(game: GameRuntime | null | undefined): 'fr' | 'en' {
    const lang = game?.language;
    return String(lang || 'fr').toLowerCase().startsWith('en') ? 'en' : 'fr';
}

export function getRampageConfig(move: Record<string, unknown> | null | undefined): MoveRampage | null {
    if (!move || typeof move.rampage !== 'object' || move.rampage === null) return null;
    const raw = move.rampage as Record<string, unknown>;
    const minTurns = Number(raw.minTurns);
    const maxTurns = Number(raw.maxTurns);
    if (!Number.isFinite(minTurns) || !Number.isFinite(maxTurns) || minTurns < 1 || maxTurns < minTurns) {
        return null;
    }
    if (raw.selfStatusAfter !== 'confused') return null;
    return { minTurns, maxTurns, selfStatusAfter: 'confused' };
}

export function getRampageState(attacker: ICreature): RampageState | null {
    const state = attacker._rampage;
    if (!state || typeof state.moveName !== 'string' || !state.moveName) return null;
    const remaining = Number(state.remaining);
    if (!Number.isFinite(remaining) || remaining <= 0) return null;
    return { moveName: state.moveName, remaining };
}

export function isRampageLocked(attacker: ICreature): boolean {
    return getRampageState(attacker) !== null;
}

export function resolveForcedRampageMove(attacker: ICreature): string | null {
    return getRampageState(attacker)?.moveName ?? null;
}

export function clearRampageState(attacker: CreatureData): void {
    attacker._rampage = null;
}

export function rollRampageTurns(config: MoveRampage, rng: () => number = Math.random): number {
    const span = config.maxTurns - config.minTurns + 1;
    return config.minTurns + Math.floor(rng() * span);
}

export function ensureRampageStarted(
    attacker: ICreature,
    moveName: string,
    config: MoveRampage,
    rng: () => number = Math.random,
): RampageState {
    const current = getRampageState(attacker);
    if (current && current.moveName === moveName) return current;

    const state: RampageState = {
        moveName,
        remaining: rollRampageTurns(config, rng),
    };
    attacker._rampage = state;
    return state;
}

function canApplyRampageConfusion(attacker: ICreature): boolean {
    if (!attacker.hasStatusEffect || !attacker.hasStatusEffect()) return true;
    const current = attacker.statusEffect?.type;
    if (!current || current === STATUS_EFFECTS.NONE) return true;
    if (BLOCKING_RAMPAGE_CONFUSION.has(current)) return false;
    return true;
}

export function tickRampageAfterAction(ctx: {
    game?: GameRuntime | null;
    attacker: ICreature;
    moveName: string;
    move: Record<string, unknown> | null | undefined;
    sourceAttack: number;
    log?: (msg: string) => void;
    onProc?: (text: string) => void;
    rng?: () => number;
}): boolean {
    const { game, attacker, moveName, move, sourceAttack, log, onProc, rng } = ctx;
    const config = getRampageConfig(move);
    if (!config || config.selfStatusAfter !== 'confused') return false;

    const state = ensureRampageStarted(attacker, moveName, config, rng);
    state.remaining -= 1;
    attacker._rampage = { ...state };

    if (state.remaining > 0) return false;

    clearRampageState(attacker);

    if (!attacker.applyStatusEffect) return false;
    if (!canApplyRampageConfusion(attacker)) return false;

    if (attacker.hasStatusEffect?.() && attacker.statusEffect?.type === STATUS_EFFECTS.CONFUSED) {
        attacker.clearStatusEffect?.();
    }

    const applied = attacker.applyStatusEffect(STATUS_EFFECTS.CONFUSED, sourceAttack, attacker);
    if (!applied) return false;

    const statusName = typeof attacker.getStatusEffectName === 'function'
        ? attacker.getStatusEffectName()
        : formatStatusLabel(game, STATUS_EFFECTS.CONFUSED);

    if (log) {
        const fr = `${attacker.name} devient confus après sa furie (${statusName}) !`;
        const en = `${attacker.name} became confused after rampaging (${statusName})!`;
        log(combatLang(game) === 'en' ? en : fr);
    }

    if (onProc) {
        onProc(formatStatusFloatingText(game, STATUS_EFFECTS.CONFUSED));
    }

    return true;
}
