/**
 * DoT status ticks (burn / poison) — shared combat + DPS accounting.
 */
import type { GameRuntime } from '../types/game.js';
import type { CreatureData, StatusEffect } from '../types/creature.js';
import { STATUS_EFFECTS } from '../../constants/balance/talentsAndCombat.js';
import { HELD_ITEMS } from '../../constants/balance/towerAndItems.js';

export const STATUS_DOT_MIN_INTERVAL_MS = 900;

export type StatusEffectWithDot = StatusEffect & {
    _lastDotTickAt?: number;
    _dotDpsCredited?: boolean;
};

export function isDotStatusType(type: string): boolean {
    return type === STATUS_EFFECTS.BURNED || type === STATUS_EFFECTS.POISONED;
}

export function computeStatusDotDamage(
    statusType: string,
    sourceAttack: number,
    sourceAttacker: { heldItem?: string | null } | null | undefined,
): number {
    if (statusType === STATUS_EFFECTS.BURNED) {
        let damage = Math.floor(sourceAttack * 0.10);
        if (sourceAttacker?.heldItem === 'flame_orb') {
            const mult = (HELD_ITEMS['flame_orb']?.effect as { burn_damage_mult?: number } | undefined)
                ?.burn_damage_mult ?? 1.5;
            damage = Math.floor(damage * mult);
        }
        return damage;
    }
    if (statusType === STATUS_EFFECTS.POISONED) {
        return Math.floor(sourceAttack * 0.05);
    }
    return 0;
}

export function shouldSkipDotCombatTick(
    statusEffect: StatusEffectWithDot,
    forceImmediate?: boolean,
    now: number = Date.now(),
): boolean {
    if (forceImmediate) return false;
    const lastTick = Number(statusEffect._lastDotTickAt) || 0;
    return lastTick > 0 && now - lastTick < STATUS_DOT_MIN_INTERVAL_MS;
}

export function markDotTickApplied(statusEffect: StatusEffectWithDot, now: number = Date.now()): void {
    statusEffect._lastDotTickAt = now;
}

export function markDotDpsCredited(statusEffect: StatusEffectWithDot): void {
    statusEffect._dotDpsCredited = true;
}

export function clearDotRuntimeFields(statusEffect: StatusEffectWithDot): void {
    delete statusEffect._lastDotTickAt;
    delete statusEffect._dotDpsCredited;
}

/** Credit one DoT tick to the DPS meter without applying combat damage (e.g. enemy died before next tick). */
export function flushPendingStatusDotDps(game: GameRuntime | null, target: CreatureData | null | undefined): void {
    if (!game || !target?.isEnemy || typeof target.hasStatusEffect !== 'function' || !target.hasStatusEffect()) {
        return;
    }
    const se = target.statusEffect as StatusEffectWithDot | undefined;
    if (!se || !isDotStatusType(se.type)) return;
    if (se._dotDpsCredited) return;

    const src = se.sourceAttacker;
    if (!src || src.isEnemy) return;
    if (typeof game.recordDamageDealt !== 'function') return;

    const amount = computeStatusDotDamage(se.type, se.sourceAttack, src);
    if (amount <= 0) return;

    game.recordDamageDealt(src, se.type, 'status', amount);
    markDotDpsCredited(se);
}
