import { getDefaultMovesPool } from '../../constants/balance/pokemonDefaultsBase.ts';
import { resolveMoveName, hasMoveDefinition, isDamagingMove, getMoveDefinition } from '../../constants/movesDb.ts';

export interface PickTrainerMovesOptions {
    ensureTypeDiversity?: boolean;
}

function getMoveElementType(moveName: string): string | null {
    const moveDef = getMoveDefinition(moveName) as Record<string, unknown> | undefined;
    if (!moveDef || typeof moveDef.type !== 'string') return null;
    return moveDef.type;
}

function scoreMove(moveName: string, preferredType: string | null): number {
    const moveDef = getMoveDefinition(moveName) as Record<string, unknown>;
    const power = (typeof moveDef.power === 'number' && Number.isFinite(moveDef.power)) ? moveDef.power : 50;
    const stabBonus = (preferredType && moveDef.type === preferredType) ? 1.35 : 1;
    const categoryBonus = (moveDef.category === 'physical' || moveDef.category === 'special') ? 1 : 0.85;
    return power * stabBonus * categoryBonus;
}

function distinctMoveTypes(moves: string[]): string[] {
    const types = new Set<string>();
    for (const moveName of moves) {
        const t = getMoveElementType(moveName);
        if (t) types.add(t);
    }
    return [...types];
}

function dominantMoveType(moves: string[]): string | null {
    const counts = new Map<string, number>();
    for (const moveName of moves) {
        const t = getMoveElementType(moveName);
        if (!t) continue;
        counts.set(t, (counts.get(t) ?? 0) + 1);
    }
    let best: string | null = null;
    let bestCount = 0;
    for (const [type, count] of counts) {
        if (count > bestCount) {
            bestCount = count;
            best = type;
        }
    }
    return best;
}

/**
 * Garantit au moins 2 types élémentaires distincts parmi les moves offensifs du set.
 * Remplace le move le moins scoré par le meilleur candidat off-type du pool.
 */
export function ensureMovesetTypeDiversity(
    moves: string[],
    pool: string[],
    preferredType: string | null = null
): string[] {
    if (moves.length <= 1) return moves;
    if (distinctMoveTypes(moves).length >= 2) return moves;

    const dominant = dominantMoveType(moves);
    if (!dominant) return moves;

    const currentSet = new Set(moves);
    const candidates = pool
        .filter((moveName) => {
            if (!moveName || currentSet.has(moveName)) return false;
            if (!hasMoveDefinition(moveName) || !isDamagingMove(moveName)) return false;
            const t = getMoveElementType(moveName);
            return t !== null && t !== dominant;
        })
        .map((moveName) => ({ moveName, score: scoreMove(moveName, preferredType) }))
        .sort((a, b) => b.score - a.score);

    const bestCandidate = candidates[0];
    if (!bestCandidate) return moves;

    const replacement = bestCandidate.moveName;
    let weakestIdx = moves.length - 1;
    let weakestScore = Infinity;
    moves.forEach((moveName, idx) => {
        const s = scoreMove(moveName, preferredType);
        if (s < weakestScore) {
            weakestScore = s;
            weakestIdx = idx;
        }
    });

    const result = [...moves];
    result[weakestIdx] = replacement;
    return result;
}

/**
 * Construit un moveset de dresseur (jusqu'à 4 attaques offensives).
 * Priorité : moves explicites / fixedMovesets → top 4 du pool espèce (power × STAB × catégorie).
 */
export function pickTrainerMoves(
    pokemonName: string,
    preferredType: string | null = null,
    explicitMoves: string[] | null = null,
    options?: PickTrainerMovesOptions
): string[] {
    const resolvedExplicit: string[] = [];
    const seenExplicit = new Set<string>();
    if (Array.isArray(explicitMoves) && explicitMoves.length > 0) {
        explicitMoves.forEach((moveName: string) => {
            if (!moveName) return;
            const resolvedName = resolveMoveName(moveName);
            if (!resolvedName || seenExplicit.has(resolvedName)) return;
            if (!hasMoveDefinition(resolvedName)) return;
            if (!isDamagingMove(resolvedName)) return;
            seenExplicit.add(resolvedName);
            resolvedExplicit.push(resolvedName);
        });
    }

    const rawPool = getDefaultMovesPool(pokemonName);
    const pool: string[] = (Array.isArray(rawPool) && rawPool.length > 0) ? rawPool : ['Charge'];
    const seen = new Set<string>();
    const ranked = pool
        .filter((moveName: string) => {
            if (!moveName || seen.has(moveName)) return false;
            seen.add(moveName);
            return hasMoveDefinition(moveName);
        })
        .filter((moveName: string) => isDamagingMove(moveName))
        .map((moveName: string) => {
            const score = scoreMove(moveName, preferredType);
            const moveDef = getMoveDefinition(moveName) as Record<string, unknown>;
            const power = (typeof moveDef.power === 'number' && Number.isFinite(moveDef.power)) ? moveDef.power : 50;
            return { moveName, score, power };
        })
        .sort((a, b) => (b.score - a.score) || (b.power - a.power))
        .slice(0, 4)
        .map((entry) => entry.moveName);

    let result: string[];
    if (resolvedExplicit.length >= 4) {
        result = resolvedExplicit.slice(0, 4);
    } else if (resolvedExplicit.length > 0) {
        ranked.forEach((moveName: string) => {
            if (resolvedExplicit.length >= 4) return;
            const resolvedName = resolveMoveName(moveName);
            if (!resolvedName || resolvedExplicit.includes(resolvedName)) return;
            resolvedExplicit.push(resolvedName);
        });
        result = resolvedExplicit.length > 0 ? resolvedExplicit : ['Charge'];
    } else {
        result = ranked.length > 0 ? ranked : ['Charge'];
    }

    if (options?.ensureTypeDiversity) {
        result = ensureMovesetTypeDiversity(result, pool, preferredType);
    }

    return result;
}
