import { TYPE_EFFECTIVENESS } from '../../constants/core.ts';

/**
 * Type matchup multiplier (attack type vs defender primary + optional secondary).
 * Uses ?? 1 so chart value 0 (immunity) is preserved (unlike || 1).
 */
export function getTypeMultiplier(
    attackType: string,
    defenderType: string,
    defenderSecondaryType?: string | null
): number {
    const chart = TYPE_EFFECTIVENESS[attackType];
    if (!chart) return 1;
    let mult = chart[defenderType] ?? 1;
    if (defenderSecondaryType) {
        mult *= chart[defenderSecondaryType] ?? 1;
    }
    return mult;
}

/** True when the attack type is fully ineffective (×0) against the defender's typing. */
export function isTypeImmune(
    attackType: string,
    defenderType: string,
    defenderSecondaryType?: string | null
): boolean {
    return getTypeMultiplier(attackType, defenderType, defenderSecondaryType) === 0;
}
