// Pokérus : système à paliers (1 = ×1.05 → 5 = ×1.25). Index 0 = pas infecté.
export const POKERUS_LEVEL_MULTIPLIERS = [1, 1.05, 1.10, 1.15, 1.20, 1.25];
const POKERUS_MAX_LEVEL = POKERUS_LEVEL_MULTIPLIERS.length - 1; // = 5
const POKERUS_DURATION_FALLBACK_MS = POKERUS_DURATION_MS;

export interface PokerusExpiryResult {
    leveledDown: boolean;
    cured: boolean;
    finalLevel: number;
    steps: number;
}

/**
 * Valeur affichée dans les floating texts de dégâts selon game.damagePopupMode.
 */
function resolveDamagePopupDisplayAmount(gameRef: GameRuntime | null | undefined, raw: number, applied: number): number {
    const g = gameRef != null ? gameRef : (typeof game !== 'undefined' ? game : null);
    if (g && g.damagePopupMode === 'true' && Number.isFinite(applied)) return Math.max(0, applied);
    return raw;
}

function resolveCombatGameRef(gameRef?: GameRuntime | null): GameRuntime | null {
    if (gameRef != null) return gameRef;
    if (typeof globalThis !== 'undefined') {
        const g = (globalThis as { game?: GameRuntime | null }).game;
        if (g != null) return g;
    }
    return typeof game !== 'undefined' ? (game) ?? null : null;
}

// ====== CLASSE CREATURE ======
export class Creature {
    [key: string]: unknown;
    // ─── Persisted properties ───
    uid!: string;
    name!: string;
    type!: string;
    secondaryType!: string | null;
    level!: number;
    rarity!: string;
    isEnemy!: boolean;
    isShiny!: boolean;
    isShadow!: boolean;
    isBoss!: boolean;
    isEpic!: boolean;
    exp!: number;
    expToNext!: number;
    prestige!: number;
    tier!: number;
    passiveTalent!: string | null;
    heldItem!: string | null;
    berserkStacks!: number;
    sentinelleStacks!: number;
    prestigeTokens!: number;
    prestigeBonuses!: PrestigeBonuses;
    pokerusUntil!: number;
    pokerusLevel!: number;
    ivHP!: number;
    ivAttack!: number;
    ivSpAttack!: number;
    ivDefense!: number;
    ivSpDefense!: number;
    ivSpeed!: number;
    ultimateAbility!: UltimateAbility | null;
    ultimateCharge!: number;
    ultimateActive!: boolean;
    megaStoneUnlocked!: boolean;
    megaVariant!: string;
    megaGauge!: number;
    statusEffect!: IStatusEffect;
    maxHp!: number;
    currentHp!: number;
    attack!: number;
    spattack!: number;
    defense!: number;
    spdefense!: number;
    speed!: number;
    maxStamina!: number;
    currentStamina!: number;
    actionGauge!: number;
    actionThreshold!: number;
    zoneMultiplier!: number;
    mainAccountCurrentHp!: number;
    currentMoves!: string[];
    movePp!: MovePpMap;
    nature!: string;
    isStarter!: boolean;
    isFavorite!: boolean;
    regionalArcId?: string;

    // ─── Runtime-only (non-serialized) ───
    static _resonanceGameRef: GameRuntime | null = null;

    static setResonanceGameRef(ref: GameRuntime | null): void {
        Creature._resonanceGameRef = ref;
    }

    _megaStatsSourceName!: string | null;
    /** Budget méga restant (ms) — ne décrémente que pendant le timer actif. */
    _megaRemainingMs!: number;
    /** Durée totale de la méga en cours (ms, pour le HUD — non sérialisé). */
    _megaDurationMs!: number;
    /** Dernier tick du timer (`null` = en pause). */
    _megaTimerLastTickAt!: number | null;
    _megaTypeBackup!: MegaTypeBackup | null;
    _abriReady?: boolean;
    _focusSashUsed?: boolean;
    _secondSouffleUsed?: boolean;
    _acharnementLastTarget?: string;
    _acharnementStacks?: number;
    nextActionSpeedMult?: number;
    combatStatStages?: {
        attack: number;
        defense: number;
        spattack: number;
        spdefense: number;
        speed: number;
        accuracy: number;
        evasion: number;
    };

    constructor(name: string, type: string, level = 1, rarity: string = RARITY.COMMON, isEnemy = false, isShiny = false, secondaryType: string | null = null, isBoss = false, isEpic = false, isShadow = false) {
        this.name = name;
        this.type = type;
        this.secondaryType = secondaryType;
        this.level = level;
        this.rarity = rarity;
        this.isEnemy = isEnemy;
        this.isShiny = isShiny;
        // Shadow est un statut alternatif à Shiny (non cumulable).
        this.isShadow = !!isShadow && !this.isShiny;
        this.isBoss = isBoss;
        this.isEpic = isEpic;
        this.exp = 0;
        this.expToNext = this.getExpToNext();
        this.prestige = 0;
        this.tier = 0;
        this.passiveTalent = null;
        this.heldItem = null;
        this.berserkStacks = 0;
        this.sentinelleStacks = 0; // Talent Sentinelle (max 5)
        this.prestigeTokens = 0; // Jetons à dépenser
        this.prestigeBonuses = { hp: 0, attack: 0, defense: 0, spattack: 0, spdefense: 0, speed: 0 }; // Jetons dépensés (1 = +5% plat)

        // Pokérus : fin du cycle 48 h du palier actuel (ms). 0 = aucun.
        this.pokerusUntil = 0;
        // Pokérus : palier 0 = sain, 1..5 = I..V. Bonus stats si pokerusUntil > now.
        this.pokerusLevel = 0;


        const generateWeightedIV = () => {
            return Math.floor(Math.pow(Math.random(), 3) * 32);
        };

        this.ivHP = generateWeightedIV();
        this.ivAttack = generateWeightedIV();
        this.ivSpAttack = generateWeightedIV();
        this.ivDefense = generateWeightedIV();
        this.ivSpDefense = generateWeightedIV();
        this.ivSpeed = generateWeightedIV();

        // Assignation de l'ultime
        this.ultimateAbility = resolveUltimateAbility(this.name, this.rarity);
        if (this.isEnemy) {
            this.ultimateAbility = scaleUltimateChargeForEnemyPvp(this.ultimateAbility);
        }
        this.ultimateCharge = 0;
        this.ultimateActive = false;

        /** Pierre méga obtenue une fois (6 IV max + Pokérus palier 5) — persistante. */
        this.megaStoneUnlocked = false;
        /** Charizard / Mewtwo : variante méga choisie ('X' | 'Y'). */
        this.megaVariant = 'X';
        /** Jauge méga 0..MEGA_GAUGE_MAX (se remplit au fil des combats ; vidée à l’activation méga). */
        this.megaGauge = 0;
        /** Nom de forme pour getPokemonBaseStats pendant la méga en combat (non sérialisé). */
        this._megaStatsSourceName = null;
        this._megaRemainingMs = 0;
        this._megaDurationMs = 0;
        this._megaTimerLastTickAt = null;
        /** Backup type / secondaryType de base pendant la méga (non sérialisé). */
        this._megaTypeBackup = null;

        this.statusEffect = {
            type: STATUS_EFFECTS.NONE,
            duration: 0,
            sourceAttack: 0,
            sourceAttacker: null,
            dodgeCount: 0,
            attackReduction: 0
        };

        this.resetCombatStatStages();

        // Assigner un talent
        if (!isEnemy && (rarity === RARITY.EPIC || rarity === RARITY.LEGENDARY)) {
            this.assignRandomTalent();
        }
        this.isStarter = false;
        this.isFavorite = false;

        // Calculer les stats
        const baseStats = this.getBaseStats();
        // IVs (flat, amplifiés par le prestige : ×(1 + prestige×0.1))
        const ivPrestigeMult = 1 + ((this.prestige || 0) * 0.1);
        baseStats.hp += this.ivHP * ivPrestigeMult;
        baseStats.attack += this.ivAttack * ivPrestigeMult;
        baseStats.spattack += this.ivSpAttack * ivPrestigeMult;
        baseStats.defense += this.ivDefense * ivPrestigeMult;
        baseStats.spdefense += this.ivSpDefense * ivPrestigeMult;
        baseStats.speed += this.ivSpeed * ivPrestigeMult;
        const rarityMultiplier = RARITY_MULTIPLIERS[this.rarity] ?? 1;
        const prestigeMultiplier = 1 + (this.prestige * 0.25);
        const tierStatBase = (BALANCE.ENEMY_TIER_STAT_MULT_BASE as number) || 1.0033;
        const tierMultiplier = this.isEnemy ? Math.pow(tierStatBase, this.tier) : 1;
        const shinyMultiplier = this.isShiny ? SHINY_STAT_MULT : 1;
        // Pokérus : multiplicateur à paliers (×1.05 → ×1.25) appliqué sur toutes les stats
        const pokerusMult = (typeof this.getPokerusMultiplier === 'function') ? this.getPokerusMultiplier() : 1;
        const shadowHpMult  = this.isShadow ? SHADOW_STAT_MULTS.hp : 1;
        const shadowAtkMult = this.isShadow ? SHADOW_STAT_MULTS.atk : 1;
        const shadowDefMult = this.isShadow ? SHADOW_STAT_MULTS.def : 1;
        const shadowSpdMult = this.isShadow ? SHADOW_STAT_MULTS.spd : 1;

        this.maxHp = Math.floor(baseStats.hp * rarityMultiplier * prestigeMultiplier * tierMultiplier * shinyMultiplier * pokerusMult * shadowHpMult);
        this.currentHp = this.maxHp;
        this.attack = Math.floor(baseStats.attack * rarityMultiplier * prestigeMultiplier * tierMultiplier * shinyMultiplier * pokerusMult * shadowAtkMult);
        this.spattack = Math.floor(baseStats.spattack * rarityMultiplier * prestigeMultiplier * tierMultiplier * shinyMultiplier * pokerusMult * shadowAtkMult);
        this.defense = Math.floor(baseStats.defense * rarityMultiplier * prestigeMultiplier * tierMultiplier * shinyMultiplier * pokerusMult * shadowDefMult);
        this.spdefense = Math.floor(baseStats.spdefense * rarityMultiplier * prestigeMultiplier * tierMultiplier * shinyMultiplier * pokerusMult * shadowDefMult);
        this.speed = Math.floor(baseStats.speed * rarityMultiplier * prestigeMultiplier * tierMultiplier * shinyMultiplier * pokerusMult * shadowSpdMult);

        // Ancien système d'endurance supprimé : la gestion de "fatigue" passe maintenant par les PP des attaques.
        this.maxStamina = 0;
        this.currentStamina = 0;
        this.actionGauge = 0;
        this.actionThreshold = (BALANCE.ATB_ACTION_THRESHOLD) || 10000;
        this.zoneMultiplier = 1;
        this.mainAccountCurrentHp = 0;

        // Attaque(s) équipées : ennemis = moveset complet (4 max) ; joueur = 1 move à la création
        if (this.isEnemy) {
            this.currentMoves = pickTrainerMoves(this.name, this.type, null);
        } else {
            const rolledMove = pickRandomDefaultMove(this.name);
            const firstMove = hasMoveDefinition(rolledMove) ? rolledMove : 'Charge';
            this.currentMoves = [firstMove];
        }

        // PP par attaque (joueur uniquement) : chaque move a un compteur { current, max }.
        this.movePp = {};
        this.currentMoves.forEach(moveName => {
            const moveDef = getMoveDefinition(moveName);
            const basePp = getBasePPForMove(moveDef);
            this.movePp[moveName] = { current: basePp, max: basePp };
        });

        // Nature de personnalité : aléatoire pour les sauvages, Hardi par défaut pour le joueur
        this.nature = isEnemy ? pickRandomNature() : DEFAULT_NATURE_ID;

        // Identifiant unique pour cette créature (réutilisé dans les loadouts)
        this.uid = `c_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;
    }

    /** Retourne l'attaque à utiliser (priorité + PP restants pour les créatures du joueur) */
    getMove(): string {
        if (!this.currentMoves || this.currentMoves.length === 0) return 'Charge';

        const forcedRampage = resolveForcedRampageMove(this);
        if (forcedRampage) {
            if (this.isEnemy || !this.movePp) return forcedRampage;
            const forcedPp = this.movePp[forcedRampage];
            if (forcedPp && forcedPp.current > 0) return forcedRampage;
        }

        // Les ennemis ne consomment pas de PP pour l'instant : on garde l'attaque principale.
        if (this.isEnemy || !this.movePp) {
            return this.currentMoves[0] ?? 'Charge';
        }

        // 1. Chercher la première attaque (ordre de priorité) avec des PP disponibles.
        for (const moveName of this.currentMoves) {
            const info = this.movePp[moveName];
            if (!info || info.current <= 0) continue;
            const def = getMoveDefinition(moveName);
            if (moveBlockedByExhaustionRule(this, moveName, def)) continue;
            return moveName;
        }

        // 2. Plus aucune attaque avec PP : on utilise la première pour appliquer le malus global.
        return this.currentMoves[0] ?? 'Charge';
    }

    getBaseStats(): PokemonBaseStat {
        const speciesKey = (this.megaStoneUnlocked && this._megaStatsSourceName)
            ? this._megaStatsSourceName
            : this.name;
        return getPokemonBaseStats(speciesKey, this.level);
    }

    /**
     * Applique les types de combat de la forme méga (sauvegarde une fois les types de base).
     */
    applyMegaCombatTypes(config: { type: string; secondaryType?: string | null }): void {
        if (!config || !config.type) return;
        if (!this._megaTypeBackup) {
            this._megaTypeBackup = { type: this.type, secondaryType: this.secondaryType };
        }
        this.type = config.type;
        this.secondaryType = config.secondaryType != null ? config.secondaryType : null;
    }

    /** Consomme le temps écoulé depuis le dernier tick et met le timer en pause. */
    pauseMegaEvolutionTimer(now?: number): void {
        if (!this._megaStatsSourceName) return;
        const t = typeof now === 'number' ? now : Date.now();
        if (this._megaTimerLastTickAt != null) {
            const elapsed = t - this._megaTimerLastTickAt;
            this._megaRemainingMs = Math.max(0, (this._megaRemainingMs || 0) - elapsed);
        }
        this._megaTimerLastTickAt = null;
    }

    /** Reprend le décompte du budget méga (si du temps reste). */
    resumeMegaEvolutionTimer(now?: number): void {
        if (!this._megaStatsSourceName || (this._megaRemainingMs || 0) <= 0) return;
        const t = typeof now === 'number' ? now : Date.now();
        this._megaTimerLastTickAt = t;
    }

    /** Temps méga restant pour l'affichage (inclut le delta en cours si timer actif). */
    getMegaRemainingMs(now?: number): number {
        if (!this._megaStatsSourceName) return 0;
        let rem = Math.max(0, Number(this._megaRemainingMs) || 0);
        const t = typeof now === 'number' ? now : Date.now();
        if (this._megaTimerLastTickAt != null) {
            rem = Math.max(0, rem - (t - this._megaTimerLastTickAt));
        }
        return rem;
    }

    /** Termine la forme méga en combat (fin timer ou fin de combat) et réapplique le ratio de PV. */
    endMegaEvolutionBattle(gameRef: GameRuntime | null, prevHpRatio: number): void {
        if (!this._megaStatsSourceName) {
            this._megaRemainingMs = 0;
            this._megaDurationMs = 0;
            this._megaTimerLastTickAt = null;
            return;
        }
        if (this._megaTypeBackup) {
            this.type = this._megaTypeBackup.type;
            this.secondaryType = this._megaTypeBackup.secondaryType;
            this._megaTypeBackup = null;
        }
        this._megaStatsSourceName = null;
        this._megaRemainingMs = 0;
        this._megaDurationMs = 0;
        this._megaTimerLastTickAt = null;
        const ratio = (typeof prevHpRatio === 'number' && prevHpRatio >= 0)
            ? Math.min(1, prevHpRatio)
            : 1;
        const g = gameRef != null ? gameRef : (typeof game !== 'undefined' ? game : null);
        if (g && typeof g.invalidateStatsCache === 'function') g.invalidateStatsCache();
        this.recalculateStats();
        const isTrainer = g ? isTrainerBattle(g) : false;
        if (this.isEnemy) return;
        if (isTrainer) {
            this.currentHp = Math.min(this.maxHp, Math.max(0, Math.floor(this.maxHp * ratio)));
        } else if (g && typeof g.getPlayerMaxHp === 'function') {
            const nh = g.getPlayerMaxHp();
            const nc = Math.min(nh, Math.max(0, Math.floor(nh * ratio)));
            this.mainAccountCurrentHp = nc;
            this.currentHp = Math.min(this.maxHp, nc);
        }
    }

    /** Si le timer méga est dépassé (timer actif uniquement), repasse en forme normale. */
    tickMegaEvolutionIfExpired(gameRef: GameRuntime | null, now?: number): boolean {
        if (!this._megaStatsSourceName || this._megaTimerLastTickAt == null) return false;
        const t = typeof now === 'number' ? now : Date.now();
        const elapsed = t - this._megaTimerLastTickAt;
        this._megaRemainingMs = Math.max(0, (this._megaRemainingMs || 0) - elapsed);
        this._megaTimerLastTickAt = t;
        if (this._megaRemainingMs > 0) return false;
        const g = gameRef != null ? gameRef : (typeof game !== 'undefined' ? game : null);
        const isTrainer = g ? isTrainerBattle(g) : false;
        let ratio = 1;
        if (isTrainer) {
            ratio = this.maxHp > 0 ? this.currentHp / this.maxHp : 1;
        } else if (g && typeof g.getPlayerMaxHp === 'function') {
            const mh = g.getPlayerMaxHp();
            ratio = mh > 0 ? (this.mainAccountCurrentHp || 0) / mh : 1;
        }
        this.endMegaEvolutionBattle(g, ratio);
        return true;
    }

    hasActivePokerus(): boolean {
        if (!this.pokerusUntil) return false;
        if (Date.now() >= this.pokerusUntil) return false;
        // Compatibilité saves anciennes : si actif sans niveau enregistré, on considère niveau 1
        if (!this.pokerusLevel || this.pokerusLevel < 1) return true;
        return this.pokerusLevel >= 1;
    }

    /** Niveau de Pokérus effectivement actif (0 si expiré ou jamais infecté). */
    getPokerusLevel(): number {
        if (!this.hasActivePokerus()) return 0;
        // Compat ancienne save : Pokérus actif sans niveau → palier 1
        return Math.max(1, Math.min(POKERUS_MAX_LEVEL, this.pokerusLevel || 1));
    }

    /** Multiplicateur Pokérus actif (1 si pas d'effet). */
    getPokerusMultiplier(): number {
        const lvl = this.getPokerusLevel();
        return POKERUS_LEVEL_MULTIPLIERS[lvl] || 1;
    }

    /**
     * Fin de cycle(s) 48 h sans réinfection : palier ≥ II → −1 (reste infecté) ; palier I → guérison.
     * Chaîne les échéances pour le rattrapage offline.
     */
    processPokerusExpiry(now: number): PokerusExpiryResult {
        let leveledDown = false;
        let cured = false;
        let steps = 0;
        const durationMs = POKERUS_DURATION_FALLBACK_MS;

        while ((this.pokerusLevel || 0) >= 1 && (this.pokerusUntil || 0) > 0 && now >= (this.pokerusUntil || 0)) {
            steps++;
            const level = this.pokerusLevel || 0;
            if (level >= 2) {
                this.pokerusLevel = level - 1;
                this.pokerusUntil = (this.pokerusUntil || 0) + durationMs;
                leveledDown = true;
            } else {
                this.pokerusLevel = 0;
                this.pokerusUntil = 0;
                cured = true;
                break;
            }
        }

        return {
            leveledDown,
            cured,
            finalLevel: this.pokerusLevel || 0,
            steps,
        };
    }

    /**
     * Infection / ré-infection (combat, propagation). Actif → +1 palier (max V) + reset 48 h.
     */
    tryInfectPokerus(now: number, opts?: { source?: string; durationMs?: number }): { infected: boolean; leveledUp: boolean; leveledDown: boolean; level: number; previousLevel: number } {
        opts = opts || {};
        const durationMs = (typeof opts.durationMs === 'number' && opts.durationMs > 0)
            ? opts.durationMs
            : POKERUS_DURATION_MS;

        this.processPokerusExpiry(now);

        const prevLevel = this.pokerusLevel || 0;
        const prevUntil = this.pokerusUntil || 0;
        const wasActive = prevUntil > now && prevLevel >= 1;

        let newLevel: number;
        if (wasActive) {
            newLevel = Math.min(POKERUS_MAX_LEVEL, prevLevel + 1);
        } else {
            newLevel = 1;
        }

        this.pokerusLevel = newLevel;
        this.pokerusUntil = now + durationMs;

        return {
            infected: true,
            leveledUp: wasActive && newLevel > prevLevel,
            leveledDown: false,
            level: newLevel,
            previousLevel: prevLevel,
        };
    }

    getExpToNext(): number {
        // Formule de base
        const baseExp = Math.floor((200 * Math.pow(1.02, this.level)) + (this.level * this.level));

        // Récupérer le multiplicateur de rareté (1.0 par défaut si non trouvé)
        const rarityMultiplier = XP_CURVE_MULTIPLIERS[this.rarity] || 1.0;

        // Appliquer le multiplicateur
        return Math.floor(baseExp * rarityMultiplier);
    }

    /** Plafond de niveau pour ce prestige (même formule que gainExp). */
    getMaxLevel(): number {
        return 100 + ((this.prestige || 0) * 10);
    }

    isAtMaxLevel(): boolean {
        return this.level >= this.getMaxLevel();
    }

    gainExp(amount: number): boolean {
        if (!this.isEnemy) {
            const gameRef = Creature._resonanceGameRef
                ?? (typeof game !== 'undefined' ? (game) : null);
            if (gameRef && typeof gameRef.isCreatureInUltimateSlot === 'function'
                && gameRef.isCreatureInUltimateSlot(this)) {
                return false;
            }
        }

        // Vérification de l'Oeuf Chance
        let finalAmount = amount;
        if (this.heldItem === 'lucky_egg') {
            finalAmount = Math.floor(finalAmount * 2); // +100% XP
        }

        // Malus d'XP lié au prestige : -2.5% XP par niveau de prestige
        // Prestige 0 → 100% XP, Prestige 1 → 97.5%, Prestige 2 → 95%, etc. (jamais négatif)
        if (this.prestige && this.prestige > 0) {
            const malusFactor = Math.max(0, 1 - 0.025 * this.prestige);
            finalAmount = Math.floor(finalAmount * malusFactor);
        }

        if (!this.isEnemy) {
            const gameRef = Creature._resonanceGameRef
                ?? (typeof game !== 'undefined' ? (game) : null);
            const catchUpMult = getAnchorCatchUpXpMult(this, gameRef);
            if (catchUpMult !== 1) {
                finalAmount = Math.floor(finalAmount * catchUpMult);
            }
        }

        this.exp += finalAmount;
        // ... le reste de la fonction gainExp reste inchangé ...
        const maxLevel = this.getMaxLevel();
        let leveledUp = false;
        while (this.exp >= this.expToNext && this.level < maxLevel) {
            this.exp -= this.expToNext;
            this.levelUp();
            leveledUp = true;
        }
        if (this.level >= maxLevel) this.exp = 0;
        if (leveledUp && !this.isEnemy) {
            const gameRef = Creature._resonanceGameRef
                ?? (typeof game !== 'undefined' ? (game) : null);
            if (gameRef) {
                const regionId =
                    typeof gameRef.getCurrentRegionId === 'function'
                        ? String(gameRef.getCurrentRegionId() || 'kanto')
                        : 'kanto';
                if (isResonanceAnchor(this, regionId)) {
                    invalidateResonanceCache(gameRef);
                }
            }
        }
        return leveledUp;
    }

    levelUp(): void {
        this.level++;
        this.expToNext = this.getExpToNext();

        const oldMaxHp = this.maxHp;

        // IMPORTANT : on délègue entièrement à recalculateStats() pour éviter
        // de dupliquer la formule et de « perdre » silencieusement les bonus
        // (jetons de prestige, synergies d'équipe, collection, zone, Shadow,
        // talent Muraille…). Sinon, après un prestige + farming, les stats
        // affichées sont incomplètes jusqu'à la prochaine recalculateStats()
        // (ex : dépense d'un jeton), ce qui provoquait un « bond » apparent.
        this.recalculateStats();

        const hpGain = this.maxHp - oldMaxHp;
        this.currentHp += hpGain;

        this.maxStamina = 3 + Math.floor((RARITY_STAMINA_BONUS[this.rarity] ?? 0) + (this.level / 6));
        this.currentStamina = this.maxStamina; // On remplit l'endurance au max à chaque level up

    }

    assignRandomTalent(): void {
        // Choix de la liste selon la rareté
        let talentPool = this.rarity === RARITY.LEGENDARY ? LEGENDARY_TALENTS : EPIC_TALENTS;

        // Ennemis : pas robustesse (évite Sturdy / survie à 1 PV sur le dernier Pokémon d'un dresseur)
        if (this.isEnemy && Array.isArray(talentPool)) {
            talentPool = talentPool.filter(t => t !== 'robustesse');
            if (talentPool.length === 0) talentPool = this.rarity === RARITY.LEGENDARY ? LEGENDARY_TALENTS : EPIC_TALENTS;
        }

        // Tirage aléatoire
        const randomIndex = Math.floor(Math.random() * talentPool.length);
        this.passiveTalent = talentPool[randomIndex] ?? null;
    }

    getTalentInfo(): Record<string, unknown> | null {
        if (!this.passiveTalent) return null;
        return (PASSIVE_TALENTS as Record<string, unknown>)[this.passiveTalent] as Record<string, unknown>;
    }

    // OPTIMISATION : Gestion Dégâts Universelle (Fix Arène & Affichage)
    takeDamage(
        damage: number,
        playerMainStats: PlayerMainStats | null = null,
        isCritical = false,
        damageCategory = 'physical',
        hitIndex = 0,
        gameRef: GameRuntime | null = null,
        silent = false,
    ): boolean {
        const gameCtx = resolveCombatGameRef(gameRef);

        // 1. Esquive (Agile)
        if (this.hasStatusEffect() && this.statusEffect.type === STATUS_EFFECTS.AGILE) {
            if (this.statusEffect.dodgeCount < STATUS_AGILE_MAX_DODGES && Math.random() < STATUS_AGILE_DODGE_CHANCE) {
                this.statusEffect.dodgeCount++;
                return false;
            }
        }

        // Abri : annule entièrement la première attaque subie (une fois par combat)
        if (this.passiveTalent === 'abri' && this._abriReady !== false && damage > 0) {
            this._abriReady = false;
            if (!silent) {
                const el = document.getElementById(this.isEnemy ? 'enemySpriteContainer' : 'playerSpriteContainer');
                if (el) showFloatingText('Abri!', el, 'ft-status', false);
            }
            return false;
        }

        // Groundium Z : −50 % sur le premier coup encaissé (avant sash / renvoi)
        if (!this.isEnemy && gameCtx && damage > 0) {
            damage = applyZRingGroundiumIncomingDamageMod(gameCtx, this, damage);
        }

        // 2. PV actuels / max (pour Ceinture Force)
        let currentHpVal;
        const trainerBattle = gameCtx ? isTrainerBattle(gameCtx) : false;
        if (!this.isEnemy) {
            currentHpVal = trainerBattle ? this.currentHp : this.mainAccountCurrentHp;
        } else {
            currentHpVal = this.currentHp;
        }

        // 3. Calcul Renvoi (Thorns / Casque Brut)
        let thornsReflect = 0;
        let helmetReflect = 0;
        if (this.hasStatusEffect() && this.statusEffect.type === STATUS_EFFECTS.THORNY) {
            thornsReflect = Math.floor(damage * STATUS_THORNY_REFLECT_RATIO);
        }
        if (this.heldItem === 'rocky_helmet') {
            const contactAttacker = gameCtx
                ? (!this.isEnemy ? gameCtx.currentEnemy : gameCtx.currentPlayerCreature)
                : null;
            if (!isContactBlockedByPunchingGlove(contactAttacker, damageCategory)) {
                helmetReflect = Math.floor(damage * (HELD_ITEMS['rocky_helmet']?.effect?.reflect_mult || 0));
            }
        }
        const reflectedDamage = thornsReflect + helmetReflect;

        // Ceinture Force : survit une fois à un coup fatal (PV à 1)
        if (this.heldItem === 'focus_sash' && !this._focusSashUsed && damage >= currentHpVal && currentHpVal > 0) {
            this._focusSashUsed = true;
            damage = Math.max(1, currentHpVal - 1);
            logMessage(this.name + " tient grâce à la Ceinture Force !");
        }

        // --- 4. APPLICATION DES DGTS (Le Fix est ici) ---

        // CAS A : C'est le JOUEUR qui prend les dégâts
        if (!this.isEnemy) {

            // Réduction des PV du Joueur (combat dresseur = currentHp, zone = mainAccountCurrentHp)
            if (gameCtx && trainerBattle) {
                this.currentHp = Math.max(0, this.currentHp - damage);
            } else {
                this.mainAccountCurrentHp = Math.max(0, this.mainAccountCurrentHp - damage);
            }

            // Talent Second Souffle — une fois par combat, si PV < 50%, soigne 40% PV max
            if (this.passiveTalent === 'second_souffle' && !this._secondSouffleUsed) {
                const _ssMaxHp = (gameCtx && trainerBattle) ? (this.maxHp || 100) : (gameCtx && typeof gameCtx.getPlayerMaxHp === 'function' ? gameCtx.getPlayerMaxHp() : (this.maxHp || 100));
                const _ssCurrentHp = (gameCtx && trainerBattle) ? (this.currentHp || 0) : (this.mainAccountCurrentHp || 0);
                if (_ssCurrentHp > 0 && _ssCurrentHp / _ssMaxHp < 0.50) {
                    this._secondSouffleUsed = true;
                    let healRatio = 0.40;
                    if (gameCtx && typeof gameCtx.getEluFactorFor === 'function') {
                        healRatio *= gameCtx.getEluFactorFor(this);
                    }
                    const healAmount = Math.floor(_ssMaxHp * healRatio);
                    if (gameCtx) {
                        applyCombatHeal(gameCtx, this, healAmount);
                    } else if (gameCtx && trainerBattle) {
                        this.currentHp = Math.min(this.maxHp, this.currentHp + healAmount);
                    } else {
                        this.mainAccountCurrentHp = Math.min(_ssMaxHp, this.mainAccountCurrentHp + healAmount);
                    }
                    if (!silent) {
                        const el = document.getElementById('playerSpriteContainer');
                        if (el) showFloatingText('Second Souffle!', el, 'ft-status', false);
                    }
                }
            }

            const _newHpAfter = (gameCtx && trainerBattle)
                ? (this.currentHp || 0)
                : (this.mainAccountCurrentHp || 0);
            const _appliedMain = Math.max(0, currentHpVal - _newHpAfter);
            const _displayMain = resolveDamagePopupDisplayAmount(gameCtx, damage, _appliedMain);

            // Affichage (couleur selon catégorie : physique ou spécial)
            if (!silent) {
                const damageTypeClass = (damageCategory === 'special') ? 'ft-damage-special' : 'ft-damage-physical';
                const container = document.getElementById('playerSpriteContainer');
                if (container) showFloatingText(formatCombatFloatingNumber(gameCtx, _displayMain), container, `ft-damage-player ${damageTypeClass}`, isCritical, hitIndex);
            }

            if (gameCtx?.stats) {
                gameCtx.stats.totalDamageTaken += damage;
                if (typeof gameCtx.checkAchievements === 'function') {
                    gameCtx.checkAchievements('totalDamageTaken');
                }
            }

            // ✅ C'EST ICI QU'ON APPLIQUE LE FIX (Renvoi de dégâts vers l'ennemi)
            if (reflectedDamage > 0 && gameCtx && gameCtx.currentEnemy && gameCtx.currentEnemy.passiveTalent !== 'sans_repos') {
                // 1. L'ennemi prend les dégâts
                const _enemyPrev = gameCtx.currentEnemy.currentHp || 0;
                gameCtx.currentEnemy.currentHp = Math.max(0, _enemyPrev - reflectedDamage);
                const _enemyApplied = Math.max(0, _enemyPrev - gameCtx.currentEnemy.currentHp);
                if (typeof gameCtx.recordDamageDealt === 'function' && _enemyApplied > 0) {
                    let leftover = _enemyApplied;
                    if (thornsReflect > 0) {
                        const part = Math.min(leftover, thornsReflect);
                        if (part > 0) gameCtx.recordDamageDealt(this, 'thorns_reflect', 'recoil', part);
                        leftover -= part;
                    }
                    if (helmetReflect > 0 && leftover > 0) {
                        const part = Math.min(leftover, helmetReflect);
                        if (part > 0) gameCtx.recordDamageDealt(this, 'rocky_helmet', 'recoil', part);
                    }
                }
                if (!silent) {
                    const reflTypeClass = (damageCategory === 'special') ? 'ft-damage-special' : 'ft-damage-physical';
                    const _reflEnemyDisp = resolveDamagePopupDisplayAmount(gameCtx, reflectedDamage, _enemyApplied);
                    const container = document.getElementById('enemySpriteContainer');
                    if (container) showFloatingText("💢" + formatCombatFloatingNumber(gameCtx, _reflEnemyDisp), container, `ft-damage-enemy ${reflTypeClass}`);
                }

                // 💀 2. VÉRIFICATION IMMÉDIATE DE LA MORT DE L'ENNEMI 💀
                // Si l'ennemi se tue en tapant, on déclenche la victoire tout de suite.
                // Ignore reflect on an already-fainted enemy (e.g. Dernière Volonté chip during winCombat).
                if (_enemyPrev > 0 && !(gameCtx.currentEnemy as unknown as Creature).isAlive(gameCtx)) {
                    logMessage(`💀 ${gameCtx.currentEnemy.name} s'est tué sur vos épines !`);

                    // On appelle la fonction de victoire du GameManager
                    gameCtx.winCombat();

                    return false; // On retourne false pour dire "Le joueur n'est pas mort", le combat est fini.
                }
            }

            // Vérification Mort du Joueur (Si l'ennemi a survécu à ses propres dégâts)
            if (gameCtx && trainerBattle) return this.currentHp <= 0;
            return this.mainAccountCurrentHp <= 0;
        }

        // CAS B : C'est l'ENNEMI qui prend les dégâts
        else {
            const _prevEnemyHp = this.currentHp || 0;
            this.currentHp = Math.max(0, this.currentHp - damage);

            // Talent Second Souffle — une fois par combat, si PV < 50%, soigne 40% PV max
            if (this.passiveTalent === 'second_souffle' && !this._secondSouffleUsed) {
                const _ssMaxHp = this.maxHp || 100;
                if (this.currentHp > 0 && this.currentHp / _ssMaxHp < 0.50) {
                    this._secondSouffleUsed = true;
                    let healRatio = 0.40;
                    if (gameCtx && typeof gameCtx.getEluFactorFor === 'function') {
                        healRatio *= gameCtx.getEluFactorFor(this);
                    }
                    const healAmount = Math.floor(_ssMaxHp * healRatio);
                    this.currentHp = Math.min(this.maxHp, this.currentHp + healAmount);
                    if (!silent) {
                        const container = document.getElementById('enemySpriteContainer');
                        if (container) {
                            showFloatingText('Second Souffle!', container, 'ft-status', false);
                        }
                    }
                }
            }

            const _appliedEnemy = Math.max(0, _prevEnemyHp - (this.currentHp || 0));
            const _displayEnemy = resolveDamagePopupDisplayAmount(gameCtx, damage, _appliedEnemy);

            // Affichage (couleur selon catégorie : physique ou spécial)
            if (!silent) {
                const damageTypeClass = (damageCategory === 'special') ? 'ft-damage-special' : 'ft-damage-physical';
                const container = document.getElementById('enemySpriteContainer');
                if (container) showFloatingText(formatCombatFloatingNumber(gameCtx, _displayEnemy), container, `ft-damage-enemy ${damageTypeClass}`, isCritical, hitIndex);
            }

            // Renvoi de dégâts vers le joueur (Si l'ennemi a des épines)
            if (reflectedDamage > 0 && gameCtx && gameCtx.currentPlayerCreature && gameCtx.currentPlayerCreature.passiveTalent !== 'sans_repos') {
                const player = gameCtx.currentPlayerCreature;
                const playerTrainerBattle = isTrainerBattle(gameCtx);

                const _refPrev = playerTrainerBattle ? (player.currentHp || 0) : (player.mainAccountCurrentHp || 0);
                if (playerTrainerBattle) {
                    player.currentHp = Math.max(0, player.currentHp - reflectedDamage);
                } else {
                    player.mainAccountCurrentHp = Math.max(0, player.mainAccountCurrentHp - reflectedDamage);
                }
                const _refNew = playerTrainerBattle ? (player.currentHp || 0) : (player.mainAccountCurrentHp || 0);
                const _refApplied = Math.max(0, _refPrev - _refNew);
                if (typeof gameCtx.recordDamageTaken === 'function' && _refApplied > 0) {
                    let leftover = _refApplied;
                    if (thornsReflect > 0) {
                        const part = Math.min(leftover, thornsReflect);
                        if (part > 0) gameCtx.recordDamageTaken(player, 'thorns_reflect', 'recoil', part);
                        leftover -= part;
                    }
                    if (helmetReflect > 0 && leftover > 0) {
                        const part = Math.min(leftover, helmetReflect);
                        if (part > 0) gameCtx.recordDamageTaken(player, 'rocky_helmet', 'recoil', part);
                    }
                }
                if (!silent) {
                    const reflTypeClass = (damageCategory === 'special') ? 'ft-damage-special' : 'ft-damage-physical';
                    const _reflPlayerDisp = resolveDamagePopupDisplayAmount(gameCtx, reflectedDamage, _refApplied);
                    const container = document.getElementById('playerSpriteContainer');
                    if (container) showFloatingText("💢" + formatCombatFloatingNumber(gameCtx, _reflPlayerDisp), container, `ft-damage-player ${reflTypeClass}`);
                }

                // Optionnel : Vérifier si le joueur meurt sur le coup des épines ennemies
                let playerDied = false;
                if (playerTrainerBattle) {
                    if (player.currentHp <= 0) playerDied = true;
                } else {
                    if (player.mainAccountCurrentHp <= 0) playerDied = true;
                }

                if (playerDied) {
                    logMessage(`💀 ${player.name} s'est tué sur les épines ennemies !`);
                    playerCreatureFaintedLogic(gameCtx);
                    return false; // Enemy is not necessarily dead, we just handled the player death.
                }
            }

            if (gameCtx?.stats) gameCtx.stats.totalDamageDealt += damage;
            return this.currentHp <= 0;
        }
    }
    /**
     * Calcule les dégâts finaux d'une attaque (Logique centralisée)
     */
    static calculateDamageOutput(
        attacker: ICreature | Creature,
        target: ICreature | Creature,
        options: {
            isCritical?: boolean;
            ultMultiplier?: number;
            ignoreDefensePct?: number;
            attackCategory?: string;
            movePower?: number;
            moveType?: string | null;
            moveName?: string;
            moveDef?: Record<string, unknown> | null;
            gameContext?: GameRuntime | null;
        } = {}
    ): number {
        const {
            isCritical = false,
            ultMultiplier = 1.0,
            ignoreDefensePct = 0,
            attackCategory = 'physical',
            movePower = 50, // Puissance par défaut (ex: Charge)
            moveType = null,
            moveName,
            moveDef,
            gameContext = null
        } = options;
        const attackType = moveType || attacker.type;

        // 1. Attaque (On utilise la valeur du proxy qui contient déjà les boosts Tour/Potions)
        const atkStatKey = attackCategory === 'special' ? 'spattack' : 'attack';
        let attack = attackCategory === 'special' ? attacker.spattack : attacker.attack;
        if (typeof (attacker as Creature).getCombatStatStageMultiplier === 'function') {
            attack = Math.floor(attack * (attacker as Creature).getCombatStatStageMultiplier(atkStatKey));
        }

        // 2. Défense (Cible)
        const defStatKey = attackCategory === 'special' ? 'spdefense' : 'defense';
        let defense = attackCategory === 'special' ? target.spdefense : target.defense;

        if (!target.isEnemy && gameContext && gameContext.getEffectiveStats) {
            const playerStats = gameContext.getEffectiveStats(target);
            defense = (attackCategory === 'special' ? playerStats.spdefense : playerStats.defense) ?? defense;
        } else if (typeof (target as Creature).getDefenseMultiplier === 'function') {
            defense = Math.floor(defense * (target as Creature).getDefenseMultiplier(gameContext));
        }

        if (typeof (target as Creature).getCombatStatStageMultiplier === 'function') {
            defense = Math.floor(defense * (target as Creature).getCombatStatStageMultiplier(defStatKey));
        }

        // Application Pénétration d'Armure (Ultime / Talent)
        if (ignoreDefensePct > 0) {
            defense = Math.floor(defense * (1 - ignoreDefensePct));
        }

        // 3. Efficacité de Type
        const effectiveness = gameContext && typeof gameContext.getTypeEffectiveness === 'function'
            ? gameContext.getTypeEffectiveness(attackType, target.type, target.secondaryType ?? null)
            : getTypeMultiplier(
                attackType,
                target.type,
                target.secondaryType ?? null
            );
        if (effectiveness === 0) return 0;

        // 4. STAB (Bonus de même type) : seulement si le type du move
        // correspond au type primaire/secondaire du Pokémon.
        const hasStab = attacker.type === attackType || (attacker.secondaryType && attacker.secondaryType === attackType);
        const stabMult = BALANCE
            ? (BALANCE.STAB_MULTIPLIER as number)
            : 1.5;
        let stab = hasStab ? stabMult : 1.0;

        // Bonus Talent "Maître Élémentaire" (Si disponible)
        if (hasStab && !attacker.isEnemy && gameContext && gameContext.getTalentStackBonus) {
            const maitreBonus = gameContext.getTalentStackBonus('maitre');
            if (maitreBonus > 0) stab *= (1 + maitreBonus);
        }

        // 5. Multiplicateurs Finaux
        let multiplier = ultMultiplier * effectiveness * stab;

        // 🎯 Objet tenu : Ceinture Pro (Expert Belt)
        // Bonus si l'attaque est super efficace (effectiveness > 1)
        if (effectiveness > 1 && attacker.heldItem === 'expert_belt') {
            const bonus = HELD_ITEMS['expert_belt']?.effect?.super_effective_bonus || 0;
            if (bonus > 0) {
                multiplier *= (1 + bonus);
            }
        }

        // Peau Métal / Charbon : +15% dégâts selon le type de l'attaque
        const heldItemDef: HeldItemDef | null = (typeof HELD_ITEMS !== 'undefined' && attacker.heldItem)
            ? (HELD_ITEMS as Record<string, HeldItemDef>)[attacker.heldItem] ?? null
            : null;
        if (heldItemDef && heldItemDef.effect && heldItemDef.effect.type_damage_bonus && heldItemDef.effect.type === attackType) {
            const bonus = heldItemDef.effect.type_damage_bonus || 0.15;
            multiplier *= (1 + bonus);
        }
        // Bandeau Muscle / Lunettes Sage : +10% dégâts physiques ou spéciaux
        if (attacker.heldItem === 'muscle_band' && attackCategory === 'physical') {
            const bonus = HELD_ITEMS['muscle_band']?.effect?.physical_damage_mult || 0.10;
            multiplier *= (1 + bonus);
        }
        if (attacker.heldItem === 'wise_glasses' && attackCategory === 'special') {
            const bonus = HELD_ITEMS['wise_glasses']?.effect?.special_damage_mult || 0.10;
            multiplier *= (1 + bonus);
        }
        multiplier *= getPunchingGloveDamageMult(attacker, attackCategory ?? 'physical');
        multiplier *= getMetronomeBandDamageMult(attacker);

        // CRIT : x1.5 de base (aligné jeux Pokémon modernes), +0.30 si Sniper,
        // + bonus collection crit_damage_mult, + chaque % de taux critique
        // au-delà de 100% converti en +0.02 dégâts (logique centralisée dans
        // Game.getCreatureCritStats pour rester cohérent avec l'UI).
        if (isCritical) {
            let critDamageMulti = 1.5;
            if (!attacker.isEnemy && gameContext && typeof gameContext.getCreatureCritDamageMult === 'function') {
                critDamageMulti = gameContext.getCreatureCritDamageMult(attacker);
            } else {
                if (attacker.passiveTalent === 'sniper') critDamageMulti += 0.30;
                if (!attacker.isEnemy && gameContext && gameContext.getCollectionBonuses) {
                    const collDmg = gameContext.getCollectionBonuses().crit_damage_mult || 0;
                    if (collDmg > 0) critDamageMulti += collDmg;
                }
            }
            multiplier *= critDamageMulti;
        }

        // Talent Opportuniste (Si cible a un statut) — amplifie par ELU
        if (attacker.passiveTalent === 'opportuniste' && target.hasStatusEffect && target.hasStatusEffect()) {
            const eluBoost = (gameContext && typeof gameContext.getEluFactorFor === 'function') ? gameContext.getEluFactorFor(attacker) : 1.0;
            multiplier *= 1 + 0.5 * eluBoost;
        }

        // Malus si le lanceur n'a plus aucune attaque avec PP (remplace l'ancien système d'endurance)
        if (!attacker.isEnemy && attacker.movePp && attacker.currentMoves && attacker.currentMoves.length > 0) {
            const hasAnyPp = attacker.currentMoves.some(name => {
                const info = attacker.movePp[name];
                return info && info.current > 0;
            });
            if (!hasAnyPp && attacker.passiveTalent !== 'robustesse') {
                multiplier *= 0.5; // Dégâts / 2
            }
        }

        // 6. Calcul Final
        const power = (typeof movePower === 'number' && Number.isFinite(movePower)) ? movePower : 50;
        const rawDamage = attack * (power / 100) * multiplier;

        // Mitigation : dégâts réduits par la défense (coef 2)
        // ✅ SÉCURITÉ : Ajout de +1 pour éviter la division par zéro
        const mitigationRatio = attack / (attack + (defense * 2) + 1);

        const finalDamage = Math.floor(rawDamage * mitigationRatio);

        // Minimum proportionnel à la puissance : préserve le ratio entre moves (ex. 80/60 = 4/3).
        // Formule: min = round(power/20) → 40→2, 60→3, 80→4, 100→5. Ainsi 60 vs 80 donnent 3 vs 4.
        const minDamageFromPower = Math.max(1, Math.round(power / 20));
        let adjustedDamage = Math.max(minDamageFromPower, finalDamage);

        // Talent Intouchable : -50% degats recus tant que les PV sont au-dessus de 75%.
        // (Auparavant : strictement full HP -> trop fragile en zone des le 1er chip damage.)
        if (target.passiveTalent === 'intouchable') {
            const INTOUCHABLE_HP_THRESHOLD = 0.75;
            let hpRatio = 0;

            if (!target.isEnemy && gameContext) {
                const trainerBattleIntouchable = isTrainerBattle(gameContext);
                if (trainerBattleIntouchable) {
                    const denom = Math.max(1, Number(target.maxHp) || 1);
                    hpRatio = Number(target.currentHp) / denom;
                } else if (typeof gameContext.getPlayerMaxHp === 'function') {
                    const zoneMaxHp = Number(gameContext.getPlayerMaxHp()) || 0;
                    const zoneCurrentHp = Number.isFinite(target.mainAccountCurrentHp) ? Number(target.mainAccountCurrentHp) : Number(target.currentHp);
                    hpRatio = zoneMaxHp > 0 ? zoneCurrentHp / zoneMaxHp : 0;
                } else {
                    const denom = Math.max(1, Number(target.maxHp) || 1);
                    hpRatio = Number(target.currentHp) / denom;
                }
            } else {
                const denom = Math.max(1, Number(target.maxHp) || 1);
                hpRatio = Number(target.currentHp) / denom;
            }

            if (hpRatio > INTOUCHABLE_HP_THRESHOLD) {
                // Reduction amplifiee par ELU (ex : 50% -> 65%) sur le porteur.
                let reduction = 0.5;
                if (gameContext && typeof gameContext.getEluFactorFor === 'function') {
                    reduction *= gameContext.getEluFactorFor(target);
                }
                reduction = Math.min(0.85, reduction);
                adjustedDamage = Math.max(1, Math.floor(adjustedDamage * (1 - reduction)));
            }
        }

        // Talent Carapace : -20% degats des attaques super-efficaces (amplifie par ELU)
        if (target.passiveTalent === 'carapace' && effectiveness > 1.0) {
            let reduction = 0.20;
            if (gameContext && typeof gameContext.getEluFactorFor === 'function') {
                reduction *= gameContext.getEluFactorFor(target);
            }
            reduction = Math.min(0.50, reduction);
            adjustedDamage = Math.max(1, Math.floor(adjustedDamage * (1 - reduction)));
        }

        // Talent Vengeance — bonus de dégâts finaux selon PV manquants (amplifie par ELU)
        if (attacker.passiveTalent === 'vengeance') {
            const hpRatio = getAttackerHpRatio(gameContext, attacker);
            let bonus = (1 - Math.min(1, hpRatio)) / 2;
            if (gameContext && typeof gameContext.getEluFactorFor === 'function') {
                bonus *= gameContext.getEluFactorFor(attacker);
            }
            adjustedDamage = Math.max(minDamageFromPower, Math.floor(adjustedDamage * (1 + bonus)));
        }

        const eluBoost = (gameContext && typeof gameContext.getEluFactorFor === 'function')
            ? gameContext.getEluFactorFor(attacker)
            : 1.0;
        adjustedDamage = applyOffensivePassiveDamageTalents(attacker, adjustedDamage, {
            movePower: power,
            moveName,
            moveDef,
            eluFactor: eluBoost,
        });

        return adjustedDamage;
    }

    heal(): void {
        this.currentHp = this.maxHp;
    }

    isAlive(gameRef?: GameRuntime | null): boolean {
        if (this.isEnemy) return (this.currentHp || 0) > 0;
        const gameCtx = resolveCombatGameRef(gameRef);
        if (gameCtx && isTrainerBattle(gameCtx)) return (this.currentHp || 0) > 0;

        if (gameCtx && !isTrainerBattle(gameCtx)) {
            const team = gameCtx.playerTeam;
            if (Array.isArray(team)) {
                let idx = team.indexOf(this);
                if (idx < 0 && this.uid) {
                    idx = team.findIndex((c) => c?.uid === this.uid);
                }
                if (idx >= 0 && isCreatureFaintedThisCombat(gameCtx, this, idx)) {
                    return false;
                }
                if (idx >= 0 && idx !== gameCtx.activeCreatureIndex) {
                    return true;
                }
            }
            const poolHp = this.mainAccountCurrentHp || 0;
            if (poolHp > 0) return true;
            const localHp = this.currentHp || 0;
            if (localHp <= 0) return false;
            const phase = gameCtx.combatState;
            if (phase === 'fighting' || phase === 'starting' || phase === 'dead') return false;
            return true;
        }

        const poolHp = this.mainAccountCurrentHp || 0;
        if (poolHp > 0) return true;
        return (this.currentHp || 0) > 0;
    }

    /**
     * @deprecated Combat uses combatSystem.performAttackWithBonusLogic only; this method is not called.
     */
    performAttack(_target: Creature, _playerMainStats: PlayerMainStats | null = null, _isPlayerAttacking = false, _game: GameRuntime | null = null): boolean {
        return false;
    }

    hasStatusEffect(): boolean {
        return this.statusEffect.type !== STATUS_EFFECTS.NONE;
    }

    applyStatusEffect(statusType: string, sourceAttack: number, sourceAttacker: Creature | null = null): boolean {
        if (this.hasStatusEffect()) return false;

        if (statusType === STATUS_EFFECTS.POISONED
            && (this.type === TYPES.STEEL || this.secondaryType === TYPES.STEEL)) {
            return false;
        }

        const DEBUFF_STATUSES = typeof STATUS_EFFECTS !== 'undefined'
            ? new Set([
                STATUS_EFFECTS.PARALYZED, STATUS_EFFECTS.FROZEN, STATUS_EFFECTS.BURNED,
                STATUS_EFFECTS.POISONED, STATUS_EFFECTS.STUNNED, STATUS_EFFECTS.SLEEP,
                STATUS_EFFECTS.CONFUSED, STATUS_EFFECTS.SCARED, STATUS_EFFECTS.MIRED
            ])
            : null;

        // Talent Metabolisme — immunise contre les alterations de statut negatives
        if (this.passiveTalent === 'metabolisme' && DEBUFF_STATUSES && DEBUFF_STATUSES.has(statusType)) {
            return false;
        }

        if (this.passiveTalent === 'mediateur' && DEBUFF_STATUSES && DEBUFF_STATUSES.has(statusType)) {
            const g = (typeof window !== 'undefined' && window.game) ? window.game : null;
            let stacks = 1;
            if (g) {
                stacks = resolveMediateurStackCount(g, this);
            }
            let resistChance = Math.min(0.70, 0.20 + 0.10 * (stacks - 1));
            if (g && typeof g.getEluFactorFor === 'function') {
                resistChance = Math.min(1.00, resistChance * g.getEluFactorFor(this));
            }
            if (Math.random() < resistChance) return false;
        }

        this.statusEffect.type = statusType;
        this.statusEffect.duration = 0;
        this.statusEffect.sourceAttack = sourceAttack;
        this.statusEffect.sourceAttacker = sourceAttacker || null;
        this.statusEffect.dodgeCount = statusType === STATUS_EFFECTS.AGILE ? 0 : 0;
        this.statusEffect.attackReduction = statusType === STATUS_EFFECTS.SCARED ? 0.10 : 0;

        const game = (typeof window !== 'undefined') ? window.game : null;
        if (game && this.isEnemy && sourceAttacker && !sourceAttacker.isEnemy && typeof game.recordStatusApplication === 'function') {
            game.recordStatusApplication(sourceAttacker, statusType);
        }

        if (game && this.isEnemy && isDotStatusType(statusType) && (this.currentHp || 0) > 0) {
            this.processStatusEffect(game, { forceImmediate: true });
        }

        return true;
    }

    clearStatusEffect(): void {
        clearDotRuntimeFields(this.statusEffect);
        this.statusEffect.type = STATUS_EFFECTS.NONE;
        this.statusEffect.duration = 0;
        this.statusEffect.sourceAttack = 0;
        this.statusEffect.sourceAttacker = null;
        this.statusEffect.dodgeCount = 0;
        this.statusEffect.attackReduction = 0;
    }

    /** Réduit la chance de retrait des debuffs sur les ennemis (maîtrise Combattant). */
    scaleDebuffDurationMastery(removalChance: number): number {
        if (!this.isEnemy || removalChance <= 0) return removalChance;
        const game = (typeof window !== 'undefined' && window.game) ? window.game : null;
        if (!game || typeof (game as { getMasteryBonus?: (t: string) => number }).getMasteryBonus !== 'function') {
            return removalChance;
        }
        if (typeof STATUS_EFFECTS === 'undefined') return removalChance;
        const debuffs = new Set([
            STATUS_EFFECTS.PARALYZED, STATUS_EFFECTS.FROZEN, STATUS_EFFECTS.BURNED,
            STATUS_EFFECTS.POISONED, STATUS_EFFECTS.STUNNED, STATUS_EFFECTS.CONFUSED,
            STATUS_EFFECTS.SCARED, STATUS_EFFECTS.MIRED
        ]);
        if (!debuffs.has(this.statusEffect.type)) return removalChance;
        let chance = removalChance;
        const mult = game.getMasteryBonus('debuff_duration_mult') || 0;
        if (mult > 0) chance = chance / (1 + mult);
        const src = this.statusEffect.sourceAttacker as { heldItem?: string | null } | null;
        if (src?.heldItem === 'terrain_extender') {
            chance = chance / 1.5;
        }
        return chance;
    }

    // OPTIMISATION : Équilibrage des durées (Le Gel part plus vite car il bloque l'action)
    getStatusRemovalChance(): number {
        const type = this.statusEffect.type;
        const tick = this.statusEffect.duration;

        // ❄️ GEL (Accéléré) : Chance de partir dès le début pour ne pas bloquer le jeu
        if (type === STATUS_EFFECTS.FROZEN) {
            if (tick === 0) return 0.20; // 20% de chance immédiate
            if (tick === 1) return 0.50; // 50% au tour suivant
            if (tick === 2) return 0.80; // 80% ensuite
            return 1.0;                  // Fini au 3ème tour max
        }

        // 💤 SOMMEIL : réveil progressif par tours (pas sur dégâts)
        if (type === STATUS_EFFECTS.SLEEP) {
            if (tick === 0) return 0.20;
            if (tick === 1) return 0.50;
            if (tick === 2) return 0.80;
            return 1.0;
        }

        // 🔥 BRÛLURE (Standard DoT)
        if (type === STATUS_EFFECTS.BURNED) {
            if (tick === 0) return 0;
            if (tick === 1) return 0.25;
            if (tick === 2) return 0.50;
            if (tick === 3) return 0.75;
            return 1.0;
        }

        // ☣️ POISON (Persistant)
        if (type === STATUS_EFFECTS.POISONED) {
            if (tick === 0) return 0;
            if (tick === 1) return 0.15;
            if (tick === 2) return 0.30;
            if (tick === 3) return 0.45;
            if (tick === 4) return 0.60;
            if (tick === 5) return 0.75;
            return 0.90; // Le poison peut durer très longtemps
        }

        // ⚡ PARALYSIE (Fixe après 10 tours)
        if (type === STATUS_EFFECTS.PARALYZED) {
            if (tick >= 10) return 1.0;
            return 0; // La paralysie est souvent permanente jusqu'au soin
        }

        // 💫 ÉTOURDISSEMENT (Court terme)
        if (type === STATUS_EFFECTS.STUNNED) {
            return 1.0; // Dure généralement 1 tour ou géré par un compteur spécifique
        }

        // AUTRES (Buffs/Debuffs temporaires)
        if (type === STATUS_EFFECTS.CONFUSED ||
            type === STATUS_EFFECTS.REINFORCED ||
            type === STATUS_EFFECTS.THORNY ||
            type === STATUS_EFFECTS.ENRAGED) {
            if (this.passiveTalent === 'metabolisme') {
                if (tick >= 4) return 1.0;
                return 0;
            }
            if (tick >= 3) return 1.0;
            return 0;
        }

        if (type === STATUS_EFFECTS.SCARED) {
            if (tick >= 4) return 1.0;
            return 0;
        }

        if (type === STATUS_EFFECTS.AGILE) {
            if (this.passiveTalent === 'metabolisme') {
                if (tick >= 5) return 1.0;
                return 0;
            }
            if (tick >= 4) return 1.0;
            return 0;
        }

        if (type === STATUS_EFFECTS.PUNCHER) {
            if (this.passiveTalent === 'metabolisme') {
                if (tick >= 1) return 1.0;
                return 0;
            }
            return 1.0; // Dure 1 seule attaque
        }

        // 🪨 EMBOURBÉ : debuff de vitesse persistant (≈ ralenti la jauge ATB).
        // Plus court que la paralysie (qui peut être permanente) car il est purement
        // statistique et n'a pas de chance d'échec d'action.
        if (type === STATUS_EFFECTS.MIRED) {
            if (tick === 0) return 0;
            if (tick === 1) return 0.10;
            if (tick === 2) return 0.20;
            if (tick === 3) return 0.40;
            if (tick === 4) return 0.70;
            return 1.0;
        }

        return 0;
    }

    // ✅ REMPLACEZ L'INTÉGRALITÉ de votre fonction processStatusEffect
    processStatusEffect(
        game: GameRuntime | null,
        opts?: { forceImmediate?: boolean },
    ): { damage: number; isDead: boolean } {
        let damage = 0;
        let isDead = false;

        if (!this.hasStatusEffect()) return { damage: 0, isDead };

        const simDotFn = (globalThis as Record<string, unknown>).__applySimCombatDamage;
        const useSimDot = !!(game && game.isOfflineSimulating && typeof simDotFn === 'function');
        const type = this.statusEffect.type;
        const playerMainStats = (game && game.playerMainStats) ? game.playerMainStats : null;
        const tickNow = Date.now();

        if (isDotStatusType(type) && shouldSkipDotCombatTick(this.statusEffect, opts?.forceImmediate, tickNow)) {
            return { damage: 0, isDead: false };
        }

        // ✅ MODIFIÉ : Détermine la bonne cible pour le FCT
        const targetContainerId = (this.isEnemy) ? 'enemySpriteContainer' : 'playerSpriteContainer';
        const targetContainer = document.getElementById(targetContainerId);

        const _dotIsTrainer = !!(game && isTrainerBattle(game));
        const _dotPrevHp = this.isEnemy ? (this.currentHp || 0) : (_dotIsTrainer ? (this.currentHp || 0) : (this.mainAccountCurrentHp || 0));

        if (type === STATUS_EFFECTS.BURNED) {
            damage = computeStatusDotDamage(
                type,
                this.statusEffect.sourceAttack,
                this.statusEffect.sourceAttacker,
            );
            if (useSimDot && game) {
                (simDotFn as (g: GameRuntime, c: Creature, d: number) => number)(game, this, damage);
                const _dotIsTrainerSim = isTrainerBattle(game);
                const _dotHp = this.isEnemy ? (this.currentHp || 0) : (_dotIsTrainerSim ? (this.currentHp || 0) : (this.mainAccountCurrentHp || 0));
                isDead = _dotHp <= 0;
            } else {
                isDead = this.takeDamage(damage, playerMainStats, false, 'special', 0, game, true);
            }

            const _dotNewHp = this.isEnemy ? (this.currentHp || 0) : (_dotIsTrainer ? (this.currentHp || 0) : (this.mainAccountCurrentHp || 0));
            const _dotApplied = Math.max(0, _dotPrevHp - _dotNewHp);

            if (targetContainer) {
                const _burnDisp = resolveDamagePopupDisplayAmount(game, damage, _dotApplied);
                showFloatingText('🔥' + formatCombatFloatingNumber(game, _burnDisp), targetContainer, 'ft-status');
            }
            if (game && _dotApplied > 0) {
                if (this.isEnemy && this.statusEffect.sourceAttacker && typeof game.recordDamageDealt === 'function') {
                    game.recordDamageDealt(this.statusEffect.sourceAttacker, type, 'status', _dotApplied);
                    markDotDpsCredited(this.statusEffect);
                } else if (!this.isEnemy && typeof game.recordDamageTaken === 'function') {
                    game.recordDamageTaken(this, type, 'status', _dotApplied);
                }
                if (!this.isEnemy && typeof game.updateCombatDisplay === 'function') {
                    game.updateCombatDisplay();
                }
            }
            markDotTickApplied(this.statusEffect, tickNow);

        } else if (type === STATUS_EFFECTS.POISONED) {
            damage = computeStatusDotDamage(
                type,
                this.statusEffect.sourceAttack,
                this.statusEffect.sourceAttacker,
            );
            if (useSimDot && game) {
                (simDotFn as (g: GameRuntime, c: Creature, d: number) => number)(game, this, damage);
                const _dotIsTrainerSim = isTrainerBattle(game);
                const _dotHp = this.isEnemy ? (this.currentHp || 0) : (_dotIsTrainerSim ? (this.currentHp || 0) : (this.mainAccountCurrentHp || 0));
                isDead = _dotHp <= 0;
            } else {
                isDead = this.takeDamage(damage, playerMainStats, false, 'special', 0, game, true);
            }

            const _dotNewHp = this.isEnemy ? (this.currentHp || 0) : (_dotIsTrainer ? (this.currentHp || 0) : (this.mainAccountCurrentHp || 0));
            const _dotApplied = Math.max(0, _dotPrevHp - _dotNewHp);

            if (targetContainer) {
                const _poisDisp = resolveDamagePopupDisplayAmount(game, damage, _dotApplied);
                showFloatingText('☣️' + formatCombatFloatingNumber(game, _poisDisp), targetContainer, 'ft-status');
            }
            if (game && _dotApplied > 0) {
                if (this.isEnemy && this.statusEffect.sourceAttacker && typeof game.recordDamageDealt === 'function') {
                    game.recordDamageDealt(this.statusEffect.sourceAttacker, type, 'status', _dotApplied);
                    markDotDpsCredited(this.statusEffect);
                } else if (!this.isEnemy && typeof game.recordDamageTaken === 'function') {
                    game.recordDamageTaken(this, type, 'status', _dotApplied);
                }
                if (!this.isEnemy && typeof game.updateCombatDisplay === 'function') {
                    game.updateCombatDisplay();
                }
            }
            markDotTickApplied(this.statusEffect, tickNow);

        } else if (type === STATUS_EFFECTS.THORNY) {
            const heal = Math.floor(this.maxHp * 0.02);

            if (game && (game.currentPlayerCreature as unknown as Creature) === this) {
                const trainerBattleThorny = isTrainerBattle(game);
                const _thPrev = trainerBattleThorny ? (this.currentHp || 0) : (this.mainAccountCurrentHp || 0);
                if (trainerBattleThorny) {
                    this.currentHp = Math.min(this.maxHp, this.currentHp + heal);
                } else if (this.mainAccountCurrentHp !== undefined) {
                    const maxHp = game.getPlayerMaxHp ? game.getPlayerMaxHp() : this.maxHp;
                    this.mainAccountCurrentHp = Math.min(maxHp, this.mainAccountCurrentHp + heal);
                }
                const _thNew = trainerBattleThorny ? (this.currentHp || 0) : (this.mainAccountCurrentHp || 0);
                const _thApplied = Math.max(0, _thNew - _thPrev);
                if (typeof game.recordHealing === 'function' && _thApplied > 0) {
                    game.recordHealing(this, 'thorny_heal', 'heal', _thApplied);
                }
                if (targetContainer) {
                    showFloatingText(formatCombatFloatingNumber(game, heal), targetContainer, 'ft-heal');
                }
            } else {
                this.currentHp = Math.min(this.maxHp, this.currentHp + heal);
                if (targetContainer) {
                    showFloatingText(formatCombatFloatingNumber(game, heal), targetContainer, 'ft-heal');
                }
            }
        }

        this.statusEffect.duration++;

        const removalChance = this.scaleDebuffDurationMastery(this.getStatusRemovalChance());
        if (Math.random() < removalChance) {
            this.clearStatusEffect();
        }

        return { damage, isDead };
    }

    canAttack(): boolean {
        if (!this.hasStatusEffect()) return true;

        const type = this.statusEffect.type;

        // Seuls ces statuts empêchent totalement de jouer
        if (type === STATUS_EFFECTS.FROZEN) return false;
        if (type === STATUS_EFFECTS.STUNNED) return false;
        if (type === STATUS_EFFECTS.SLEEP) return false;

        // La paralysie a une chance de bloquer, mais ne bloque pas tout le temps
        if (type === STATUS_EFFECTS.PARALYZED) {
            return Math.random() > 0.25; // 25% de chance de rater
        }

        // Note : SCARED a été retiré, il laisse attaquer mais moins fort.

        return true;
    }

    static readonly COMBAT_STAT_STAGE_CAP = 3;
    static readonly COMBAT_STAT_STAGE_STEP = 0.10;

    resetCombatStatStages(): void {
        this.combatStatStages = {
            attack: 0,
            defense: 0,
            spattack: 0,
            spdefense: 0,
            speed: 0,
            accuracy: 0,
            evasion: 0,
        };
        this.nextActionSpeedMult = 1;
        this.partialTrap = null;
    }

    getCombatStatStage(stat: 'attack' | 'defense' | 'spattack' | 'spdefense' | 'speed' | 'accuracy' | 'evasion'): number {
        return this.combatStatStages?.[stat] ?? 0;
    }

    getCombatStatStageMultiplier(stat: 'attack' | 'defense' | 'spattack' | 'spdefense' | 'speed' | 'accuracy' | 'evasion'): number {
        const stage = this.getCombatStatStage(stat);
        if (!stage) return 1;
        const mult = 1 + stage * Creature.COMBAT_STAT_STAGE_STEP;
        return Math.max(0.1, mult);
    }

    adjustCombatStatStage(stat: 'attack' | 'defense' | 'spattack' | 'spdefense' | 'speed' | 'accuracy' | 'evasion', delta: number): number {
        if (shouldBlockNegativeStatStage(this, delta)) return 0;
        if (!this.combatStatStages) this.resetCombatStatStages();
        const cap = Creature.COMBAT_STAT_STAGE_CAP;
        const prev = this.combatStatStages![stat];
        const next = Math.max(-cap, Math.min(cap, prev + delta));
        this.combatStatStages![stat] = next;
        return next - prev;
    }

    getAttackMultiplier(gameContext: GameRuntime | null = null): number {
        let multiplier = 1.0;
        const hasCran = this.passiveTalent === 'cran';

        if (this.hasStatusEffect()) {
            const type = this.statusEffect.type;
            const cranAtkMult = cranAttackStatusMultiplier(type, hasCran);

            // ÉQUILIBRAGE : La peur réduit l'attaque de 40% (Debuff) au lieu de bloquer
            if (type === STATUS_EFFECTS.SCARED) {
                multiplier *= cranAtkMult ?? 0.60;
            }
            // ÉQUILIBRAGE : Enragé reste un gros buff risque/récompense
            else if (type === STATUS_EFFECTS.ENRAGED) {
                multiplier *= 1.30;
            }
            // PUNCHER reste x2 (One Shot setup)
            else if (type === STATUS_EFFECTS.PUNCHER) {
                multiplier *= 2.0;
            }
            // La paralysie ne réduit pas l'attaque, elle réduit la Vitesse (géré ailleurs)
        }

        if (hasCran && this.hasStatusEffect()) {
            const eluBoost = (gameContext && typeof gameContext.getEluFactorFor === 'function') ? gameContext.getEluFactorFor(this) : 1.0;
            const fallback = cranFallbackAttackBonus(true, this.statusEffect.type, eluBoost);
            if (fallback > 0) multiplier *= 1 + fallback;
        }

        // Talent Courant Alternatif — +20% degats si statut positif (ENRAGE, RENFORCE, AGILE, PUNCHER)
        if (this.passiveTalent === 'courant_alternatif' && this.hasStatusEffect()) {
            const BUFF_STATUSES = [STATUS_EFFECTS.ENRAGED, STATUS_EFFECTS.REINFORCED, STATUS_EFFECTS.AGILE, STATUS_EFFECTS.PUNCHER];
            if (BUFF_STATUSES.includes(this.statusEffect.type)) {
                const eluBoost = (gameContext && typeof gameContext.getEluFactorFor === 'function') ? gameContext.getEluFactorFor(this) : 1.0;
                multiplier *= 1 + 0.20 * eluBoost;
            }
        }

        // Talent Berserker (+5% par stack, max 10) — amplifie par ELU
        if (this.passiveTalent === 'berserker') {
            const eluBoost = (gameContext && typeof gameContext.getEluFactorFor === 'function') ? gameContext.getEluFactorFor(this) : 1.0;
            multiplier += (this.berserkStacks * 0.05) * eluBoost;
        }
        // Talent Sentinelle (+20% ATK / ATK Spe par allie KO, max 5 stacks) — amplifie par ELU
        if (this.passiveTalent === 'sentinelle' && (this.sentinelleStacks || 0) > 0) {
            const eluBoost = (gameContext && typeof gameContext.getEluFactorFor === 'function') ? gameContext.getEluFactorFor(this) : 1.0;
            multiplier += this.sentinelleStacks * 0.20 * eluBoost;
        }
        // Talent Acharnement (+10% degats par attaque consecutive sur meme cible, max 3 stacks) — amplifie par ELU
        if (this.passiveTalent === 'acharnement' && (this._acharnementStacks || 0) > 0) {
            const eluBoost = (gameContext && typeof gameContext.getEluFactorFor === 'function') ? gameContext.getEluFactorFor(this) : 1.0;
            multiplier += this._acharnementStacks! * 0.10 * eluBoost;
        }
        return multiplier;
    }

    getDefenseMultiplier(gameContext: GameRuntime | null = null): number {
        let multiplier = 1.0;

        if (this.hasStatusEffect() && this.statusEffect.type === STATUS_EFFECTS.REINFORCED) {
            multiplier *= 1.25;
        }

        if (this.passiveTalent === 'dernier_rempart') {
            const hpRatio = getAttackerHpRatio(gameContext, this);
            let bonus = (1 - Math.min(1, hpRatio)) * DERNIER_REMPART_DEF_MAX_BONUS;
            if (gameContext && typeof gameContext.getEluFactorFor === 'function') {
                bonus *= gameContext.getEluFactorFor(this);
            }
            multiplier *= 1 + bonus;
        }

        return multiplier;
    }

    getSpeedMultiplier(gameContext: GameRuntime | null = null): number {
        let multiplier = 1.0;
        const hasCran = this.passiveTalent === 'cran';

        if (this.hasStatusEffect()) {
            const type = this.statusEffect.type;
            const cranSpdMult = cranSpeedStatusMultiplier(type, hasCran);

            // ÉQUILIBRAGE : Enragé donne de la vitesse
            if (type === STATUS_EFFECTS.ENRAGED) multiplier *= 1.15;

            // ÉQUILIBRAGE : Paralysie nerfée de -50% à -25%
            if (type === STATUS_EFFECTS.PARALYZED) multiplier *= cranSpdMult ?? 0.75;

            // ÉQUILIBRAGE : Embourbé est purement statistique (-40% vitesse).
            // Plus fort que la paralysie côté vitesse, mais ne fait pas rater d'attaque.
            if (type === STATUS_EFFECTS.MIRED) multiplier *= cranSpdMult ?? 0.60;
        }

        // Talent Sentinelle (+20% Vitesse par allie KO, max 5 stacks) — amplifie par ELU
        if (this.passiveTalent === 'sentinelle' && (this.sentinelleStacks || 0) > 0) {
            const eluBoost = (gameContext && typeof gameContext.getEluFactorFor === 'function') ? gameContext.getEluFactorFor(this) : 1.0;
            multiplier *= 1 + this.sentinelleStacks * 0.20 * eluBoost;
        }

        // Talent Dernier Élan — bonus vitesse selon PV perdus (amplifie par ELU)
        if (this.passiveTalent === 'dernier_elan') {
            const hpRatio = getAttackerHpRatio(gameContext, this);
            let bonus = (1 - Math.min(1, hpRatio)) * DERNIER_ELAN_SPEED_MAX_BONUS;
            if (gameContext && typeof gameContext.getEluFactorFor === 'function') {
                bonus *= gameContext.getEluFactorFor(this);
            }
            multiplier *= 1 + bonus;
        }

        const nextActionMult = (typeof this.nextActionSpeedMult === 'number' && this.nextActionSpeedMult > 1)
            ? this.nextActionSpeedMult
            : 1;
        return multiplier * this.getCombatStatStageMultiplier('speed') * nextActionMult;
    }

    getStatusEffectName(): string {
        if (!this.hasStatusEffect()) return '';

        const names = {
            'burned': 'Brûlé',
            'poisoned': 'Empoisonné',
            'frozen': 'Gelé',
            'paralyzed': 'Paralysé',
            'stunned': 'Étourdi',
            'sleep': 'Endormi',
            'confused': 'Confus',
            'scared': 'Effrayé',
            'reinforced': 'Renforcé',
            'agile': 'Agile',
            'thorny': 'Épineux',
            'enraged': 'Enragé',
            'puncher': 'Puncheur',
            'mired': 'Embourbé'
        };

        return (names as Record<string, string>)[this.statusEffect.type] || this.statusEffect.type;
    }

    // OPTIMISATION : Calcul des stats AVEC Synergies incluses
    recalculateStats(): void {
        // Plafond niveau joueur (cohérent avec gainExp / prestige) — corrige ex. Shadow easter egg avec niveau du lead trop haut.
        if (!this.isEnemy) {
            const prestigeVal = Number(this.prestige) || 0;
            const maxLevel = 100 + prestigeVal * 10;
            if (this.level > maxLevel) {
                this.level = maxLevel;
                this.exp = 0;
            }
        }

        const savedLevel = this.level;
        const savedPrestige = this.prestige;
        let resonanceSwapped = false;
        if (!this.isEnemy) {
            const gameRef = Creature._resonanceGameRef
                ?? (typeof game !== 'undefined' ? (game) : null);
            if (gameRef) {
                const eff = getEffectivePrestigeAndLevel(this, gameRef);
                if (eff.capped) {
                    this.prestige = eff.prestige;
                    this.level = eff.level;
                    resonanceSwapped = true;
                }
            }
        }

        // 1️⃣ Base stats & IVs (IV amplifié par le prestige : ×(1 + prestige×0.1))
        const baseStats = this.getBaseStats();
        const ivPrestigeMult = 1 + ((this.prestige || 0) * 0.1);
        baseStats.hp += this.ivHP * ivPrestigeMult;
        baseStats.attack += this.ivAttack * ivPrestigeMult;
        baseStats.spattack += this.ivSpAttack * ivPrestigeMult;
        baseStats.defense += this.ivDefense * ivPrestigeMult;
        baseStats.spdefense += this.ivSpDefense * ivPrestigeMult;
        baseStats.speed += this.ivSpeed * ivPrestigeMult;

        // 2️⃣ Multiplicateurs Individuels
        const rarityMultiplier = RARITY_MULTIPLIERS[this.rarity] || 1;
        const prestigeMultiplier = 1 + (this.prestige * 0.25);
        const tierStatBase = (BALANCE.ENEMY_TIER_STAT_MULT_BASE as number) || 1.0033;
        const tierMultiplier = this.isEnemy ? Math.pow(tierStatBase, this.tier) : 1;
        const shinyMultiplier = this.isShiny ? SHINY_STAT_MULT : 1;
        const pokerusMult = this.getPokerusMultiplier();
        const shadowHpMult  = this.isShadow ? SHADOW_STAT_MULTS.hp : 1;
        const shadowAtkMult = this.isShadow ? SHADOW_STAT_MULTS.atk : 1;
        const shadowDefMult = this.isShadow ? SHADOW_STAT_MULTS.def : 1;
        const shadowSpdMult = this.isShadow ? SHADOW_STAT_MULTS.spd : 1;
        const zoneMultiplier = this.zoneMultiplier || 1;

        // 3️⃣ Bonus Jetons Prestige (Stats perso) — % plat : ajouté au multiplicateur global, pas multiplié
        if (!this.prestigeBonuses) this.prestigeBonuses = { hp: 0, attack: 0, defense: 0, spattack: 0, spdefense: 0, speed: 0 };
        const PRESTIGE_TOKEN_PCT = 0.05; // +5% par jeton, appliqué en additif sur le mult global
        const pFlatHP = this.prestigeBonuses.hp * PRESTIGE_TOKEN_PCT;
        const pFlatATK = this.prestigeBonuses.attack * PRESTIGE_TOKEN_PCT;
        const pFlatSpATK = this.prestigeBonuses.spattack * PRESTIGE_TOKEN_PCT;
        const pFlatDEF = this.prestigeBonuses.defense * PRESTIGE_TOKEN_PCT;
        const pFlatSpDEF = this.prestigeBonuses.spdefense * PRESTIGE_TOKEN_PCT;
        const pFlatSPD = this.prestigeBonuses.speed * PRESTIGE_TOKEN_PCT;

        // 4️⃣ RÉCUPÉRATION DES SYNERGIES (C'est ici que la magie opère !)
        let syn = {
            attack_mult: 1, spattack_mult: 1, defense_mult: 1, spdefense_mult: 1,
            max_hp_mult: 1, speed_mult: 1
        };
        if (!this.isEnemy && typeof game !== 'undefined' && game?.getActiveSynergies) {
            syn = { ...syn, ...game.getActiveSynergies() };
        }

        let baseSpAttackMult = syn.spattack_mult;
        let baseSpDefenseMult = syn.spdefense_mult;

        if (!this.isEnemy && typeof game !== 'undefined' && game?.getCollectionBonuses) {
            const collBonuses = (game).getCollectionBonuses();
            syn.attack_mult += collBonuses.attack_mult || 0;
            syn.defense_mult += collBonuses.defense_mult || 0;
            syn.max_hp_mult += collBonuses.max_hp_mult || 0;
            syn.speed_mult += collBonuses.speed_mult || 0;
            baseSpAttackMult += collBonuses.spattack_mult || 0;
            baseSpDefenseMult += collBonuses.spdefense_mult || 0;
        }

        // 5️⃣ Calcul Final : mult global = (rarity * prestige * ... * pokerus * syn) + bonus jetons en % plat
        const multBase = rarityMultiplier * prestigeMultiplier * tierMultiplier * shinyMultiplier * zoneMultiplier * pokerusMult;

        this.maxHp = Math.floor(
            baseStats.hp * (multBase * syn.max_hp_mult + pFlatHP)
        );

        // Talent Muraille — 10% PV max convertis en ATK / SP-ATK (amplifie par ELU si actif)
        let murailleRatio = 0;
        if (this.passiveTalent === 'muraille') {
            murailleRatio = 0.10;
            if (!this.isEnemy && typeof game !== 'undefined' && game && typeof game.getEluFactorFor === 'function') {
                murailleRatio *= game.getEluFactorFor(this);
            }
        }
        const attackBonus = murailleRatio > 0 ? Math.floor(this.maxHp * murailleRatio) : 0;

        this.attack = Math.floor(
            baseStats.attack * (multBase * syn.attack_mult + pFlatATK) + attackBonus
        );

        this.spattack = Math.floor(
            baseStats.spattack * (multBase * baseSpAttackMult + pFlatSpATK) + attackBonus
        );

        this.defense = Math.floor(
            baseStats.defense * (multBase * syn.defense_mult + pFlatDEF)
        );

        this.spdefense = Math.floor(
            baseStats.spdefense * (multBase * baseSpDefenseMult + pFlatSpDEF)
        );

        // Statuts alternatifs (Shadow) : buff PV/ATK/DEF/VIT (multiplicateurs asymétriques)
        if (this.isShadow) {
            this.maxHp = Math.floor(this.maxHp * shadowHpMult);
            this.attack = Math.floor(this.attack * shadowAtkMult);
            this.spattack = Math.floor(this.spattack * shadowAtkMult);
            this.defense = Math.floor(this.defense * shadowDefMult);
            this.spdefense = Math.floor(this.spdefense * shadowDefMult);
        }

        this.speed = Math.floor(
            baseStats.speed * (multBase * syn.speed_mult + pFlatSPD)
        );
        if (this.isShadow) {
            this.speed = Math.floor(this.speed * shadowSpdMult);
        }

        const natureMults = getNatureStatMultipliers(normalizeNatureId(this.nature));
        this.attack = Math.floor(this.attack * natureMults.attack);
        this.spattack = Math.floor(this.spattack * natureMults.spattack);
        this.defense = Math.floor(this.defense * natureMults.defense);
        this.spdefense = Math.floor(this.spdefense * natureMults.spdefense);
        this.speed = Math.floor(this.speed * natureMults.speed);

        if (!this.isEnemy && typeof game !== 'undefined' && game?.playerTeam?.includes?.(this)) {
            if (typeof game.getUltimateSlotTeamFlatBonus === 'function') {
                const ultBonus = game.getUltimateSlotTeamFlatBonus();
                this.maxHp += ultBonus.hp;
                this.attack += ultBonus.attack;
                this.spattack += ultBonus.spattack;
                this.defense += ultBonus.defense;
                this.spdefense += ultBonus.spdefense;
                this.speed += ultBonus.speed;
            }
        }

        // 6️⃣ Sécurité HP
        if (this.currentHp === undefined || isNaN(this.currentHp)) this.currentHp = this.maxHp;
        else this.currentHp = Math.min(this.currentHp, this.maxHp);

        if (this.isEnemy && this.currentHp <= 0) {
            this.currentHp = this.maxHp;
        }

        if (resonanceSwapped) {
            this.level = savedLevel;
            this.prestige = savedPrestige;
        }
    }

    /**
     * Retourne, sans muter la créature, le détail complet du calcul de chaque stat.
     * Utilisé par l'outil de transparence "Détails des stats" du modal créature.
     */
    getStatsBreakdown(): Record<string, unknown> {
        const baseSpecies = this.getBaseStats();
        const hasPokerus = typeof this.hasActivePokerus === 'function' ? this.hasActivePokerus() : false;
        const pokerusLevel = (typeof this.getPokerusLevel === 'function') ? this.getPokerusLevel() : (hasPokerus ? 1 : 0);
        const pokerusMult = (typeof this.getPokerusMultiplier === 'function') ? this.getPokerusMultiplier() : (hasPokerus ? 1.05 : 1);
        const ivPrestigeMult = 1 + ((this.prestige || 0) * 0.1);

        const rarityMultiplier = (typeof RARITY_MULTIPLIERS !== 'undefined' && RARITY_MULTIPLIERS[this.rarity]) || 1;
        const prestigeMultiplier = 1 + ((this.prestige || 0) * 0.25);
        const tierStatBase = (BALANCE.ENEMY_TIER_STAT_MULT_BASE as number) || 1.0033;
        const tierMultiplier = this.isEnemy ? Math.pow(tierStatBase, this.tier || 0) : 1;
        const shinyMultiplier = this.isShiny ? SHINY_STAT_MULT : 1;
        const zoneMultiplier = this.zoneMultiplier || 1;
        const shadowHpMult  = this.isShadow ? SHADOW_STAT_MULTS.hp : 1;
        const shadowAtkMult = this.isShadow ? SHADOW_STAT_MULTS.atk : 1;
        const shadowDefMult = this.isShadow ? SHADOW_STAT_MULTS.def : 1;
        const shadowSpdMult = this.isShadow ? SHADOW_STAT_MULTS.spd : 1;
        const multBase = rarityMultiplier * prestigeMultiplier * tierMultiplier * shinyMultiplier * zoneMultiplier * pokerusMult;

        const PRESTIGE_TOKEN_PCT = 0.05;
        const tokensBonuses = this.prestigeBonuses || { hp: 0, attack: 0, defense: 0, spattack: 0, spdefense: 0, speed: 0 };

        // Synergies / collection
        let syn = {
            attack_mult: 1, spattack_mult: 1, defense_mult: 1, spdefense_mult: 1,
            max_hp_mult: 1, speed_mult: 1
        };
        let collBonuses = null;
        if (!this.isEnemy && typeof game !== 'undefined' && game?.getActiveSynergies) {
            try { syn = { ...syn, ...game.getActiveSynergies() }; } catch (_) { /* noop */ }
        }
        let baseSpAttackMult = syn.spattack_mult;
        let baseSpDefenseMult = syn.spdefense_mult;
        if (!this.isEnemy && typeof game !== 'undefined' && game?.getCollectionBonuses) {
            try {
                collBonuses = game.getCollectionBonuses() || null;
                if (collBonuses) {
                    syn.attack_mult += collBonuses.attack_mult || 0;
                    syn.defense_mult += collBonuses.defense_mult || 0;
                    syn.max_hp_mult += collBonuses.max_hp_mult || 0;
                    syn.speed_mult += collBonuses.speed_mult || 0;
                    baseSpAttackMult += collBonuses.spattack_mult || 0;
                    baseSpDefenseMult += collBonuses.spdefense_mult || 0;
                }
            } catch (_) { /* noop */ }
        }

        // Définition par stat : on factorise les particularités (talent Muraille / Shadow / synergie)
        const statDefs = [
            { key: 'hp',        ivKey: 'ivHP',        synMult: syn.max_hp_mult,  shadowMult: shadowHpMult,  talent: false },
            { key: 'attack',    ivKey: 'ivAttack',    synMult: syn.attack_mult,  shadowMult: shadowAtkMult, talent: true  },
            { key: 'spattack',  ivKey: 'ivSpAttack',  synMult: baseSpAttackMult, shadowMult: shadowAtkMult, talent: true  },
            { key: 'defense',   ivKey: 'ivDefense',   synMult: syn.defense_mult, shadowMult: shadowDefMult, talent: false },
            { key: 'spdefense', ivKey: 'ivSpDefense', synMult: baseSpDefenseMult,shadowMult: shadowDefMult, talent: false },
            { key: 'speed',     ivKey: 'ivSpeed',     synMult: syn.speed_mult,   shadowMult: shadowSpdMult, talent: false }
        ];

        let murailleRatio = 0;
        if (this.passiveTalent === 'muraille') {
            murailleRatio = 0.10;
            if (!this.isEnemy && typeof game !== 'undefined' && game && typeof game.getEluFactorFor === 'function') {
                murailleRatio = scaleTalentRatio(0.10, game.getEluFactorFor(this));
            }
        }

        // On commence par calculer maxHp (nécessaire pour le bonus Muraille des stats d'attaque)
        const computeStat = (def: typeof statDefs[number], opts: { ivOverride?: number; pokerusOverride?: number; maxHpForTalent?: number } = {}) => {
            const ivRaw = (opts && opts.ivOverride !== undefined) ? opts.ivOverride : (Number(this[def.ivKey as CreatureIvKey]) || 0);
            const ivContribution = ivRaw * ivPrestigeMult;
            const localPokerusMult = (opts && opts.pokerusOverride !== undefined) ? opts.pokerusOverride : pokerusMult;
            const baseSp = baseSpecies[def.key as BaseStatKey] || 0;
            const additive = baseSp + ivContribution;
            // Recompose multBase si le pokérus est overridé (variante "sans Pokérus")
            const localMultBase = (localPokerusMult === pokerusMult)
                ? multBase
                : (rarityMultiplier * prestigeMultiplier * tierMultiplier * shinyMultiplier * zoneMultiplier * localPokerusMult);
            const tokenAdd = (tokensBonuses[def.key as keyof PrestigeBonuses] || 0) * PRESTIGE_TOKEN_PCT;
            const totalMult = localMultBase * def.synMult + tokenAdd;
            let value = Math.floor(additive * totalMult);
            const talentBonus = (def.talent && murailleRatio > 0 && opts && opts.maxHpForTalent)
                ? Math.floor(opts.maxHpForTalent * murailleRatio)
                : 0;
            if (talentBonus) {
                value = Math.floor(additive * totalMult + talentBonus);
            }
            // Statut Shadow appliqué après le floor
            const beforeShadow = value;
            if (def.shadowMult !== 1) value = Math.floor(value * def.shadowMult);
            return {
                base: baseSp,
                iv: ivRaw,
                ivMax: 31,
                ivPrestigeMult,
                ivContribution,
                pokerusMult: localPokerusMult,
                additive,
                rarityMult: rarityMultiplier,
                prestigeMult: prestigeMultiplier,
                shinyMult: shinyMultiplier,
                tierMult: tierMultiplier,
                zoneMult: zoneMultiplier,
                synergyMult: def.synMult,
                multBase: localMultBase,
                tokenAdd,
                totalMult,
                talentBonus,
                shadowMult: def.shadowMult,
                beforeShadow,
                final: value
            };
        };

        // 1) maxHp d'abord. On utilise la valeur PRÉ-shadow comme base pour le talent
        //    Muraille, conformément à recalculateStats() (Shadow s'applique après le floor).
        const hpDef = statDefs[0];
        if (!hpDef) {
            throw new Error('Creature.getStatBreakdown: missing hp definition');
        }
        const hpBeforeShadow = (overrides: { ivOverride?: number; pokerusOverride?: number } = {}) =>
            computeStat(hpDef, overrides).beforeShadow;

        const hpBreak = computeStat(hpDef, {});
        const maxHpForTalent = hpBreak.beforeShadow;

        // 2) Toutes les stats avec maxHp dispo pour le bonus Muraille
        const stats: Record<string, StatBreakdownEntry> = {};
        statDefs.forEach(def => {
            if (def.key === 'hp') {
                stats.hp = hpBreak;
                return;
            }
            stats[def.key] = computeStat(def, { maxHpForTalent });
        });

        const natureId = normalizeNatureId(this.nature);
        const natureMults = getNatureStatMultipliers(natureId);
        (['attack', 'spattack', 'defense', 'spdefense', 'speed'] as const).forEach((statKey) => {
            const entry = stats[statKey];
            if (!entry) return;
            const mult = natureMults[statKey];
            if (mult === 1) return;
            entry.natureMult = mult;
            entry.final = Math.floor(entry.final * mult);
        });

        // 3) Variantes "sans IV" et "sans Pokérus" — propage les overrides Pokérus/IV HP pour Muraille
        const variants: Record<string, { withoutIv: number; withoutPokerus: number; ivContribution: number; pokerusContribution: number }> = {};
        statDefs.forEach(def => {
            const usesMurailleHp = def.talent && murailleRatio > 0;
            const variantOpts = (overrides: { ivOverride?: number; pokerusOverride?: number }) => {
                const o: { ivOverride?: number; pokerusOverride?: number; maxHpForTalent?: number } = { ...overrides };
                if (usesMurailleHp) {
                    if (overrides.pokerusOverride !== undefined) {
                        o.maxHpForTalent = hpBeforeShadow({ pokerusOverride: overrides.pokerusOverride });
                    } else if (def.key === 'hp' && overrides.ivOverride !== undefined) {
                        o.maxHpForTalent = hpBeforeShadow({ ivOverride: overrides.ivOverride });
                    } else {
                        o.maxHpForTalent = maxHpForTalent;
                    }
                } else if (def.talent) {
                    o.maxHpForTalent = maxHpForTalent;
                }
                return o;
            };
            const noIv = computeStat(def, variantOpts({ ivOverride: 0 }));
            const noPkrs = computeStat(def, variantOpts({ pokerusOverride: 1 }));
            variants[def.key] = {
                withoutIv: noIv.final,
                withoutPokerus: noPkrs.final,
                ivContribution: (stats[def.key]?.final ?? 0) - noIv.final,
                pokerusContribution: (stats[def.key]?.final ?? 0) - noPkrs.final
            };
        });

        let ultimateSlotUnlocked = false;
        let ultimateSlotTransferPct = 0;
        let ultimateSlotMentorName: string | null = null;
        if (!this.isEnemy && typeof game !== 'undefined' && game) {
            const gameRef = game;
            ultimateSlotUnlocked = typeof gameRef.isUltimateSlotUnlocked === 'function'
                ? gameRef.isUltimateSlotUnlocked()
                : isUltimateSlotUnlocked(gameRef);
            if (ultimateSlotUnlocked) {
                ultimateSlotTransferPct = Math.round(
                    (typeof gameRef.getUltimateSlotTransferRate === 'function'
                        ? gameRef.getUltimateSlotTransferRate()
                        : 0) * 100,
                );
                ultimateSlotMentorName = gameRef.ultimateSlot?.name
                    ? String(gameRef.ultimateSlot.name)
                    : null;
                const onTeam = Array.isArray(gameRef.playerTeam)
                    && gameRef.playerTeam.some(
                        (c) => c === this || (c?.uid && this.uid && String(c.uid) === String(this.uid)),
                    );
                if (onTeam && typeof gameRef.getUltimateSlotTeamFlatBonus === 'function') {
                    const ultimateFlat = gameRef.getUltimateSlotTeamFlatBonus();
                    const statFieldMap: Record<string, keyof PlayerMainStats> = {
                        hp: 'hp',
                        attack: 'attack',
                        spattack: 'spattack',
                        defense: 'defense',
                        spdefense: 'spdefense',
                        speed: 'speed',
                    };
                    for (const [key, field] of Object.entries(statFieldMap)) {
                        const bonus = Number(ultimateFlat[field]) || 0;
                        const entry = stats[key];
                        if (bonus > 0 && entry) {
                            entry.ultimateSlotBonus = bonus;
                            entry.final += bonus;
                        }
                    }
                }
            }
        }

        // Métadonnées pour l'affichage
        const meta = {
            name: this.name,
            level: this.level,
            rarity: this.rarity,
            prestige: this.prestige || 0,
            isShiny: !!this.isShiny,
            isShadow: !!this.isShadow,
            isEnemy: !!this.isEnemy,
            tier: this.tier || 0,
            hasPokerus,
            pokerusUntil: this.pokerusUntil || 0,
            pokerusLevel,
            pokerusMaxLevel: POKERUS_MAX_LEVEL,
            zoneMultiplier,
            ivPrestigeMult,
            pokerusMult,
            passiveTalent: this.passiveTalent || null,
            nature: natureId,
            natureMults,
            murailleRatio,
            tokens: { ...tokensBonuses },
            multipliers: {
                rarity: rarityMultiplier,
                prestige: prestigeMultiplier,
                shiny: shinyMultiplier,
                tier: tierMultiplier,
                zone: zoneMultiplier,
                pokerus: pokerusMult,
                multBase
            },
            collectionApplied: !!collBonuses,
            combatStatStages: this.combatStatStages
                ? { ...this.combatStatStages }
                : { attack: 0, defense: 0, spattack: 0, spdefense: 0, speed: 0 },
            ultimateSlotUnlocked,
            ultimateSlotTransferPct,
            ultimateSlotMentorName,
        };

        return { meta, stats, variants };
    }



    serialize(): CreatureData {
        const persistType = this._megaTypeBackup ? this._megaTypeBackup.type : this.type;
        const persistSecondary = this._megaTypeBackup ? this._megaTypeBackup.secondaryType : this.secondaryType;
        let ultChargeOut = Math.max(0, Math.floor(Number(this.ultimateCharge) || 0));
        if (this.ultimateAbility && typeof this.ultimateAbility.chargeNeeded === 'number') {
            ultChargeOut = Math.min(this.ultimateAbility.chargeNeeded, ultChargeOut);
        }
        return {
            uid: this.uid,
            name: this.name,
            type: persistType,
            secondaryType: persistSecondary,
            level: this.level,
            rarity: this.rarity,
            isEnemy: this.isEnemy,
            isShiny: this.isShiny,
            isShadow: this.isShadow,
            isBoss: this.isBoss,
            isEpic: this.isEpic,
            maxHp: this.maxHp,
            currentHp: this.currentHp,
            attack: this.attack,
            spattack: this.spattack,
            defense: this.defense,
            spdefense: this.spdefense,
            speed: this.speed,
            exp: this.exp,
            expToNext: this.expToNext,
            currentStamina: this.currentStamina,
            maxStamina: this.maxStamina,
            prestige: this.prestige,
            passiveTalent: this.passiveTalent,
            tier: this.tier,
            zoneMultiplier: this.zoneMultiplier,
            ivHP: this.ivHP,
            ivAttack: this.ivAttack,
            ivSpAttack: this.ivSpAttack,
            ivDefense: this.ivDefense,
            ivSpDefense: this.ivSpDefense,
            ivSpeed: this.ivSpeed,
            heldItem: this.heldItem,
            prestigeTokens: this.prestigeTokens,
            prestigeBonuses: this.prestigeBonuses,
            currentMoves: this.currentMoves,
            movePp: this.movePp,
            nature: normalizeNatureId(this.nature),
            isStarter: !!this.isStarter,
            isFavorite: !!this.isFavorite,
            regionalArcId: this.regionalArcId,
            berserkStacks: this.berserkStacks,
            sentinelleStacks: this.sentinelleStacks,
            ultimateAbility: this.ultimateAbility,
            ultimateActive: this.ultimateActive,
            megaGauge: this.megaGauge,
            megaStoneUnlocked: !!this.megaStoneUnlocked,
            megaVariant: megaEvolutionEntryHasVariants(this.name)
                ? normalizeMegaVariant(this.name, this.megaVariant)
                : undefined,
            actionGauge: this.actionGauge,
            actionThreshold: this.actionThreshold,
            // sourceAttacker is a runtime combat ref (Creature) — never persist (circular JSON).
            statusEffect: {
                type: this.statusEffect.type,
                duration: this.statusEffect.duration,
                sourceAttack: this.statusEffect.sourceAttack,
                sourceAttacker: null,
                dodgeCount: this.statusEffect.dodgeCount,
                attackReduction: this.statusEffect.attackReduction
            },
            mainAccountCurrentHp: this.mainAccountCurrentHp,
            pokerusUntil: this.pokerusUntil || 0,
            pokerusLevel: this.pokerusLevel || 0,
            ultimateCharge: ultChargeOut
        };
    }

    // ✅ REMPLACEZ L'INTÉGRALITÉ de votre fonction deserialize(data) PAR CELLE-CI
    static deserialize(data: CreatureData): Creature {
        const creature = new Creature(
            data.name,
            data.type,
            data.level,
            data.rarity,
            data.isEnemy || false,
            data.isShiny || false,
            data.secondaryType || null,
            data.isBoss || false,   // ✅ LIGNE AJOUTÉE
            data.isEpic || false,   // ✅ LIGNE AJOUTÉE
            data.isShadow || false  // Shadow (non-cumulable avec shiny)
        );
        creature.ivHP = data.ivHP || 0;
        creature.ivAttack = data.ivAttack || 0;
        creature.ivSpAttack = data.ivSpAttack || 0;
        creature.ivDefense = data.ivDefense || 0;
        creature.ivSpDefense = data.ivSpDefense || 0;
        creature.ivSpeed = data.ivSpeed || 0;
        creature.nature = normalizeNatureId(
            typeof data.nature === 'string' ? data.nature : undefined,
        );
        creature.maxHp = data.maxHp;
        creature.currentHp = data.currentHp;
        creature.attack = data.attack;
        creature.spattack = data.spattack || 0;
        creature.defense = data.defense;
        creature.spdefense = data.spdefense || 0;
        creature.speed = data.speed;
        creature.exp = data.exp || 0;
        creature.expToNext = data.expToNext || 100;
        // Endurance legacy (désormais inutilisée pour le combat, mais lue pour compatibilité)
        creature.currentStamina = data.currentStamina || 0;
        creature.maxStamina = data.maxStamina || 0;
        creature.prestige = data.prestige || 0;
        creature.passiveTalent = data.passiveTalent || null;
        creature.tier = data.tier || 0;
        creature.zoneMultiplier = data.zoneMultiplier || 1;
        creature.heldItem = data.heldItem || null;
        creature.actionGauge = 0;
        creature.prestigeTokens = data.prestigeTokens || 0;
        creature.prestigeBonuses = data.prestigeBonuses || { hp: 0, attack: 0, defense: 0, spattack: 0, spdefense: 0, speed: 0 };
        creature.isStarter = !!data.isStarter;
        creature.isFavorite = !!data.isFavorite;
        if (typeof data.regionalArcId === 'string' && data.regionalArcId) {
            creature.regionalArcId = data.regionalArcId;
        }
        creature.pokerusUntil = data.pokerusUntil || 0;
        creature.megaStoneUnlocked = !!data.megaStoneUnlocked;
        if (megaEvolutionEntryHasVariants(creature.name)) {
            creature.megaVariant = normalizeMegaVariant(creature.name, data.megaVariant);
        } else {
            creature.megaVariant = 'X';
        }

        // Rétrocompatibilité : si une vieille save a un Pokérus actif sans niveau, on le considère palier 1
        if (typeof data.pokerusLevel === 'number') {
            creature.pokerusLevel = Math.max(0, Math.min(POKERUS_MAX_LEVEL, Math.floor(data.pokerusLevel)));
        } else if ((data.pokerusUntil || 0) > 0) {
            creature.pokerusLevel = 1;
        } else {
            creature.pokerusLevel = 0;
        }

        // Rétrocompatibilité : l'ancien système utilisait "currentMove" (string)
        if (data.currentMoves && Array.isArray(data.currentMoves)) {
            creature.currentMoves = data.currentMoves;
        } else if (data.currentMove && typeof data.currentMove === 'string') {
            creature.currentMoves = [data.currentMove];
        } else {
            creature.currentMoves = ['Charge'];
        }

        // Migration save: retirer les attaques sans dégâts et normaliser les noms.
        if (Array.isArray(creature.currentMoves)) {
            const cleanedMoves = creature.currentMoves
                .map(name => resolveMoveName(name))
                .filter(name => {
                    if (!name) return false;
                    if (typeof hasMoveDefinition === 'function' && !hasMoveDefinition(name)) return false;
                    if (typeof isDamagingMove === 'function' && !isDamagingMove(name)) return false;
                    return true;
                });
            creature.currentMoves = cleanedMoves.length > 0 ? cleanedMoves : ['Charge'];
        }

        // Restauration des PP par attaque (ou initialisation si absent)
        creature.movePp = data.movePp || {};
        if (!creature.movePp) creature.movePp = {};
        creature.currentMoves.forEach(name => {
            if (!creature.movePp[name]) {
                const def = getMoveDefinition(name);
                const basePp = getBasePPForMove(def);
                creature.movePp[name] = { current: basePp, max: basePp };
            }
        });

        // Identifiant unique pour les loadouts et autres références
        creature.uid = data.uid || (`c_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`);

        creature.ultimateActive = false;
        const rawUltCharge = data.ultimateCharge;
        if (rawUltCharge != null && String(rawUltCharge) !== '') {
            const num = typeof rawUltCharge === 'number' ? rawUltCharge : Number(rawUltCharge);
            if (Number.isFinite(num)) {
                let q = Math.floor(num);
                const cap = creature.ultimateAbility && typeof creature.ultimateAbility.chargeNeeded === 'number'
                    ? creature.ultimateAbility.chargeNeeded
                    : null;
                if (cap != null) q = Math.max(0, Math.min(cap, q));
                else q = Math.max(0, q);
                creature.ultimateCharge = q;
            }
        }

        creature.recalculateStats();


        return creature;
    }
}



// ====== CLASSE EGG ======
export class Egg {
    rarity: string;

    constructor(rarity: string = RARITY.COMMON) {
        this.rarity = rarity;
    }

    open(): Creature {
        return this.generateCreatureOnOpen();
    }

    getCreatureRarityOnOpen(): string {
        const roll = Math.random();
        if (this.rarity === RARITY.RARE) return roll < 0.3 ? RARITY.RARE : RARITY.COMMON;
        if (this.rarity === RARITY.EPIC) return roll < 0.3 ? RARITY.EPIC : RARITY.RARE;
        if (this.rarity === RARITY.LEGENDARY) return roll < 0.3 ? RARITY.LEGENDARY : RARITY.EPIC;
        return RARITY.COMMON;
    }

    generateCreatureOnOpen(): Creature {
        const eggRarity = this.rarity;
        const rarity = this.getCreatureRarityOnOpen();
        const poolForRarity = POKEMON_POOL[rarity] || POKEMON_POOL[RARITY.COMMON] || {};

        // --- 1. CRÉATION DU "GRAND PANIER" ---
        // On rassemble tous les noms de tous les types dans une seule liste
        let allNames: string[] = [];
        Object.keys(poolForRarity).forEach(type => {
            const names = poolForRarity[type];
            if (names && names.length > 0) {
                allNames = allNames.concat(names);
            }
        });

        // Sécurité : Si la liste est vide (ne devrait pas arriver)
        if (allNames.length === 0) {
            debugError(`Erreur Critique : Aucun Pokémon trouvé pour la rareté ${rarity} depuis un oeuf ${eggRarity}.`);
            return new Creature('Pikachu', TYPES.ELECTRIC, 1, RARITY.COMMON, false, false, null);
        }

        // --- 2. PIOCHER LE POKÉMON (régions débloquées + boost région courante + radar Pokédex) ---
        const radarTargets = (typeof game !== 'undefined' && game && game.getEggRadarTargets)
            ? game.getEggRadarTargets()
            : ((typeof game !== 'undefined' && game && game.getPokedexRadarTargets)
                ? game.getPokedexRadarTargets()
                : [])
            ;
        const gameRef = (typeof game !== 'undefined' ? game : null);
        const name =
            pickEggSpeciesFromPool(gameRef, allNames, radarTargets)
            ?? filterEggSpeciesNamesForProgress(gameRef, allNames)[0]
            ?? 'Pikachu';
        const pickedName = name;

        // --- 3. RETROUVER SON TYPE ---
        // Puisqu'on a choisi le nom en premier, il faut retrouver son type
        let type: string = TYPES.NORMAL; // Valeur par défaut
        for (const t in poolForRarity) {
            const typePool = poolForRarity[t];
            if (typePool?.includes(pickedName)) {
                type = t;
                break;
            }
        }

        // --- Suite de votre fonction (inchangée) ---
        const secondaryType = POKEMON_SECONDARY_TYPES[pickedName] || null;

        let shinyChance = 1 / 8192; // Base 1/8192
        if (typeof game !== 'undefined' && game !== null) { // Utilisation de window.game car 'game' peut ne pas être dans la portée locale
            const shinyBoost = game.getActiveBoostMultiplier ? game.getActiveBoostMultiplier('shiny') : 0;
            let upgradeBonus = 0;
            if (game.upgrades && game.upgrades.shinyHunt) {
                upgradeBonus = game.upgrades.shinyHunt.level * 0.05;
            }
            const eggMasteryShiny = game.getMasteryBonus ? (game.getMasteryBonus('egg_shiny_chance') || 0) : 0;
            shinyChance *= (1 + shinyBoost + upgradeBonus + eggMasteryShiny);
        }
        const isShiny = Math.random() < shinyChance;

        return new Creature(pickedName, type, 1, rarity, false, isShiny, secondaryType);
    }
    // ▲▲▲ FIN DE LA FONCTION MODIFIÉE ▲▲▲
}

// ====== EXPORTS ======
if (typeof window !== 'undefined') {
    const w = window as unknown as Record<string, unknown>;
    w.Creature = Creature;
    w.Egg = Egg;
}
