import { MOVES_DB, resolveMoveName, hasMoveDefinition, isDamagingMove } from '../movesDb.ts';

type MovesTable = Record<string, string[]>;

let movesTable: MovesTable | null = null;
let loadPromise: Promise<void> | null = null;
let pendingOverrides: Record<string, string[]> | null = null;

function publishAccessors(): void {
    const g = globalThis as Record<string, unknown>;
    g.getDefaultMovesPool = getDefaultMovesPool;
    g.pickRandomDefaultMove = pickRandomDefaultMove;
    if (typeof window !== 'undefined') {
        const w = window as unknown as Record<string, unknown>;
        w.getDefaultMovesPool = getDefaultMovesPool;
        w.pickRandomDefaultMove = pickRandomDefaultMove;
    }
}

function publishTable(table: MovesTable): void {
    const g = globalThis as Record<string, unknown>;
    g.POKEMON_DEFAULT_MOVES = table;
    if (typeof window !== 'undefined') {
        (window as unknown as Record<string, unknown>).POKEMON_DEFAULT_MOVES = table;
    }
}

function applyOverrides(table: MovesTable, overrides: Record<string, string[]>): void {
    const canResolve = resolveMoveName;
    const canFilterDefinition = hasMoveDefinition;
    const canFilterDamage = isDamagingMove;

    Object.keys(overrides).forEach((poke) => {
        const raw = overrides[poke] || [];
        const resolved = canResolve ? raw.map((m: string) => canResolve(m)) : raw;
        const filtered = resolved.filter((m: string) => {
            if (!m) return false;
            if (canFilterDefinition && !canFilterDefinition(m)) return false;
            if (canFilterDamage && !canFilterDamage(m)) return false;
            return true;
        });
        table[poke] = filtered.length ? filtered : ['Charge'];
    });
}

/** Enregistre les overrides niveau. Appliques tout de suite si la table est deja la. */
export function queueLevelupDefaultMovesOverrides(overrides: Record<string, string[]> | null): void {
    if (!overrides || typeof overrides !== 'object') return;
    pendingOverrides = overrides;
    if (movesTable) applyOverrides(movesTable, overrides);
}

export function isDefaultMovesLoaded(): boolean {
    return movesTable != null;
}

/** Charge le chunk des learnsets. Un echec oublie la promesse pour qu'un appel suivant reessaie. */
export function ensureDefaultMovesLoaded(): Promise<void> {
    if (movesTable) return Promise.resolve();
    if (loadPromise) return loadPromise;
    loadPromise = import('./pokemonDefaultMovesTable.ts')
        .then((mod) => {
            const table = mod.POKEMON_DEFAULT_MOVES;
            if (pendingOverrides) applyOverrides(table, pendingOverrides);
            movesTable = table;
            publishTable(table);
        })
        .catch((err: unknown) => {
            loadPromise = null;
            throw err;
        });
    return loadPromise;
}

export function getDefaultMovesPool(pokemonName: string): string[] {
    const rawPool: string[] | undefined = movesTable && pokemonName ? movesTable[pokemonName] : undefined;
    const source: (string | { name: string })[] = (Array.isArray(rawPool) && rawPool.length) ? rawPool : ['Charge'];

    const hasMovesDb = !!MOVES_DB;
    const seen = new Set<string>();
    const names: string[] = [];
    source.forEach((entry) => {
        if (!entry) return;
        const rawName = typeof entry === 'string' ? entry : entry.name;
        if (!rawName) return;

        const resolvedName = resolveMoveName(rawName);
        if (!resolvedName) return;
        if (hasMovesDb && !hasMoveDefinition(resolvedName)) return;
        if (hasMovesDb && !isDamagingMove(resolvedName)) return;
        if (seen.has(resolvedName)) return;

        seen.add(resolvedName);
        names.push(resolvedName);
    });

    return names.length ? names : ['Charge'];
}

export function pickRandomDefaultMove(pokemonName: string): string {
    const pool = getDefaultMovesPool(pokemonName);
    if (!pool.length) return 'Charge';
    return pool[Math.floor(Math.random() * pool.length)] || 'Charge';
}

/** Remet la table a vide. Reserve aux tests du chargement differe. */
export function resetDefaultMovesForTests(): void {
    movesTable = null;
    loadPromise = null;
}

publishAccessors();

// Acces direct : Vitest remplace import.meta.env.VITEST, pas une copie de env.
if (import.meta.env.VITEST) {
    await ensureDefaultMovesLoaded();
}
