/**
 * @file combatApi.ts
 * Typed access to combat helpers without a static import of combatSystem.ts.
 *
 * Why: combatSystem.ts imports Creature.ts and src/stores/team.svelte.ts ($state).
 * Importing combatSystem from gameCombatSystem.ts or Creature.ts at top-level breaks Vitest
 * (see TypeScriptFinal rule #10, combatCaptureLogic.ts pattern).
 *
 * combatSystem.ts registers implementations on globalThis at load (COMBAT_LEGACY_GLOBALS).
 * Call sites use this module instead of `declare function combatText` / `typeof` guards.
 */

import type { GameRuntime } from '../types/game.js';
import type { CreatureData, ICreature } from '../types/creature.js';

function combatGlobal<K extends string>(name: K): unknown {
    return (globalThis as Record<string, unknown>)[name];
}

export function combatText(
    game: GameRuntime,
    key: string,
    fallbackFr: string,
    fallbackEn: string,
    vars: Record<string, unknown> = {},
): string {
    const fn = combatGlobal('combatText');
    if (typeof fn !== 'function') return fallbackFr;
    return (fn as (g: GameRuntime, k: string, fr: string, en: string, v: Record<string, unknown>) => string)(
        game, key, fallbackFr, fallbackEn, vars,
    );
}

export function applyCombatHeal(
    game: GameRuntime,
    creature: CreatureData | ICreature,
    amount: number,
    opts?: Record<string, unknown>,
): number {
    const fn = combatGlobal('applyCombatHeal');
    if (typeof fn !== 'function') return 0;
    return (fn as (g: GameRuntime, c: CreatureData | ICreature, n: number, o?: Record<string, unknown>) => number)(
        game, creature, amount, opts,
    );
}

export function applyPlayerOffensivePassiveDamageMods(
    game: GameRuntime,
    attacker: ICreature,
    target: ICreature,
    damage: number,
): number {
    const fn = combatGlobal('applyPlayerOffensivePassiveDamageMods');
    if (typeof fn !== 'function') return damage;
    return (fn as (g: GameRuntime, a: ICreature, t: ICreature, d: number) => number)(game, attacker, target, damage);
}

export function playerCreatureFaintedLogic(game: GameRuntime): void {
    const fn = combatGlobal('playerCreatureFaintedLogic');
    if (typeof fn === 'function') (fn as (g: GameRuntime) => void)(game);
}
